const top_kogmaw = {
  champion: '코그모',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (Q)\'부식성 침\'으로 가렌의 방어력을 낮추며 멀리서 견제하세요. 가렌이 (Q)\'결정타\'를 쓰고 달려와 침묵 평타를 맞지 않도록 사거리를 유지하며 (E)\'공허의 분비물\'로 둔화를 유도하는 것이 좋아요. 가렌이 (P)\'인내심\'으로 체력을 회복하기 전에 꾸준히 피해를 입히는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 가렌이 (Q)\'결정타\'로 달려들기 전에 먼저 타격을 입히세요. 가렌이 (W)\'용기\'를 사용하여 보호막을 얻으면 딜교환을 멈추고, (E)\'심판\'의 회전 피해가 들어오는 동안에는 최대한 뒤로 물러나야 해요. (Q)\'부식성 침\'으로 가렌의 방어력을 낮춘 상태에서 공격하면 더 효과적이에요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 대상이 잃은 체력이 많을수록 피해가 커지니 체력이 낮을 때는 조심하세요. (R)\'살아있는 곡사포\'로 가렌의 체력을 미리 깎아두면 가렌이 다가오기 전에 압박할 수 있어요. 가렌이 (Q)\'결정타\'로 돌진할 수 있으니 라인을 너무 밀기보다는 정글러의 위치를 확인하며 라인을 관리하세요.', item: '광전사의 군화와 구인수의 격노검을 가세요. 공격 속도를 높여서 (W)\'생체마법 폭격\'의 지속 피해를 극대화하기 위해서예요.', spell: '점멸과 점화를 추천해요. 점화로 가렌의 (P)\'인내심\' 회복을 억제하며 (R)\'살아있는 곡사포\'로 적을 마무리하세요.' },
    '갱플랭크': { lv1: '갱플랭크의 (Q)\'혀어어어업상\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으니 체력을 아끼며 막타를 챙기세요. (Q)\'부식성 침\'을 맞혀 방어력을 낮추고 공격 속도를 얻은 뒤 짧게 평타를 넣고 빠지세요. 갱플랭크가 (E)\'화약통\'을 깔아두면 통 근처에서 미니언을 먹지 말고 거리를 두세요.', lv3: '갱플랭크가 깔아둔 (E)\'화약통\' 근처에서 싸우면 폭발 시 둔화와 피해를 입으니 조심하세요. (E)\'공허의 분비물\'로 갱플랭크의 이동을 방해하며 (W)\'생체마법 폭격\'의 추가 피해를 입히세요. 갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하기 전에 (Q)\'부식성 침\'을 활용해 압박해야 해요.', lv6: '(R)\'살아있는 곡사포\'를 사용해 체력이 낮은 갱플랭크를 저격하며 킬각을 노리세요. 갱플랭크가 (R)\'포탄 세례\'로 넓은 범위에 둔화를 걸면 무리하게 진입하지 말고 거리를 유지하세요. 갱플랭크의 (W)\'괴혈병 치료\'가 빠진 타이밍에 맞춰 적극적으로 딜을 넣으세요.', item: '판금 장화와 구인수의 격노검을 가세요. 판금 장화는 갱플랭크의 기본 공격 피해를 줄여주고, 구인수의 격노검은 (W)\'생체마법 폭격\'의 효율을 높여줘요.', spell: '점멸과 정화를 추천해요. 정화로 (E)\'화약통\' 폭발과 (R)\'포탄 세례\'의 둔화를 풀 수 있고, 점멸로 통이 터지기 전에 거리를 벌릴 수 있어요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 견제와 둔화를 걸고 (P)\'서비스 시간\'으로 체력을 회복하며 압박해요. (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 최대한 거리를 벌리며 평타 견제를 해주세요. 술통이 굴러오는 경로를 잘 보고 피하면서 막타를 챙기는 것이 중요해요.', lv3: '(E)\'몸통 박치기\'의 공중으로 띄우는 효과에 맞으면 이어지는 콤보에 당하니 주의하세요. (W)\'취중 분노\'를 사용하여 피해를 줄이는 동안에는 딜교를 피하고, 그 이후에 (W)\'생체마법 폭격\'으로 사거리를 늘려 일방적으로 공격하세요. 그라가스가 진입하려 하면 (E)\'공허의 분비물\'을 발밑에 깔아 둔화시켜 거리를 벌리세요.', lv6: '(R)\'술통 폭발\'에 맞으면 적 진영이나 포탑 쪽으로 밀려날 수 있으니 위치 선정에 신경 쓰세요. 상대 체력이 낮아지면 (R)\'살아있는 곡사포\'를 사용해 안전한 거리에서 마무리 킬각을 보세요. 정글러가 함께 진입할 때 (E)\'공허의 분비물\'로 경로를 방해하며 (R)\'살아있는 곡사포\'로 지원 사격을 하세요.', item: '구인수의 격노검을 첫 코어로 선택해 (W)\'생체마법 폭격\'의 퍼센트 피해 효율을 극대화하세요. 신발은 마법 저항력을 주고 (Q)\'술통 굴리기\'의 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'의 체력 회복을 점화로 억제해야 소모전에서 앞설 수 있어요.' },
    '그웬': { lv1: '1~2레벨에는 (W)\'생체마법 폭격\'을 사용하여 공격 사거리를 늘리고 (Q)\'부식성 침\'으로 그웬의 방어력을 낮추며 거리를 유지하세요. 그웬이 (E)\'돌격가위\'로 돌진해 오면 곧바로 뒤로 물러나 거리를 다시 벌리고, 평타 견제는 돌진이 빠진 뒤에 이어가세요.', lv3: '(W)\'생체마법 폭격\'을 켠 상태에서 (E)\'공허의 분비물\'을 맞춰 그웬의 이동 속도를 늦춘 뒤 (Q)\'부식성 침\'을 적중시키며 딜교환을 하세요. (W)\'신성한 안개\'는 대상 지정만 막으니 위치를 지정해 나가는 (E)\'공허의 분비물\'과 (Q)\'부식성 침\'은 안개 속의 그웬에게도 맞아요. 다만 안개 안에서는 그웬의 방어력과 마법 저항력이 올라가니 안개가 걷힌 뒤에 딜교환을 이어가세요.', lv6: '(R)\'살아있는 곡사포\'를 활용해 멀리서 포탄을 던져 그웬의 체력을 미리 깎아두고 거리를 유지하세요. 그웬이 (R)\'바느질\'로 둔화를 걸며 밀고 들어오면 (E)\'공허의 분비물\'로 이동 속도를 늦추며 정글러를 호출하고 위험한 상황을 피해야 해요.', item: '첫 코어 아이템은 구인수의 격노검을 가고 신발은 헤르메스의 발걸음을 선택하세요. 그웬의 마법 피해를 줄이고 강인함을 얻어 둔화를 견디는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 그웬은 기본 공격으로 체력을 회복하므로 점화로 그 회복을 줄여야 해요.' },
    '나르': { lv1: '나르가 (Q)\'부메랑 던지기\'로 멀리서 견제하며 둔화를 걸 수 있으니 거리를 유지하세요. (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 공격 속도를 얻으며 미니언을 챙기세요. 나르가 (W)\'슝슝\' 효과를 받으며 다가오면 최대한 뒤로 물러나야 해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘려 나르가 (E)\'폴짝\'으로 접근하기 전에 먼저 타격하세요. 나르의 (Q)\'부메랑 던지기\' 궤적을 피하면서 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추면 좋아요. 나르의 분노가 차올라 메가 나르가 될 것 같으면 교환을 멈추고 뒤로 빠지세요.', lv6: '메가 나르가 (R)\'나르!\'를 사용해 벽으로 밀쳐 기절시키는 것을 조심하며 거리를 벌리세요. (R)\'살아있는 곡사포\'를 활용해 멀리서 나르를 압박하고 체력이 낮은 적을 마무리하세요. 나르가 메가 나르 상태일 때는 정글러의 도움을 받으며 라인을 당기는 것이 안전해요.', item: '구인수의 격노검을 첫 코어로 선택해 공격 속도와 적중 시 효과를 챙기세요. 신발은 공격 속도를 높여주는 광전사의 군화를 신으면 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화를 사용해 나르의 돌진 이후에도 거리를 벌리며 공격을 이어가세요.' },
    '나서스': { lv1: '1~2레벨에는 나서스가 (Q)\'흡수의 일격\'으로 미니언 막타를 먹으며 성장하니 (Q)\'부식성 침\'으로 먼저 견제해 미니언에 접근하기 어렵게 하세요. 코그모의 사거리를 살려 거리를 유지하며 평타 견제를 이어가세요. 나서스가 붙으면 (E)\'공허의 분비물\'로 둔화를 걸고 물러나세요.', lv3: '나서스가 (W)\'쇠약\'을 사용해 다가오면 (E)\'공허의 분비물\'로 이동 속도를 늦추고 멀리 도망가세요. (W)\'생체마법 폭격\'을 켠 상태에서 지속적으로 공격하되 (E)\'영혼의 불길\' 장판 위에서는 싸우지 마세요. (Q)\'부식성 침\'을 맞춰 방어력을 낮춰두면 지속적으로 피해를 입히기 좋아요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나니 무리하게 다가가지 마세요. 체력이 낮은 나서스에게 (R)\'살아있는 곡사포\'를 맞춰 마무리하거나 거리를 두고 압박해요. 라인을 계속 밀어 넣어 나서스가 (Q)\'흡수의 일격\'으로 중첩을 쌓는 것을 방해하세요.', item: '구인수의 격노검을 첫 코어로 가세요. 신발은 기본 공격으로 받는 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 나서스의 (W)\'쇠약\' 둔화 속에서도 거리를 벌리며 카이팅하기 편해요.' },
    '녹턴': { lv1: '(Q)\'부식성 침\'을 사용하여 원거리에서 지속적으로 견제하며 체력을 깎아두세요. 녹턴이 (Q)\'황혼의 인도자\'를 맞히고 빠른 속도로 접근하려 하니 항상 일정한 거리를 유지하며 뒤로 물러나야 해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 공격 사거리를 늘리고 상대가 다가오지 못하게 계속 공격하세요. 녹턴이 (E)\'말할 수 없는 공포\'를 걸면 즉시 사거리 밖으로 벗어나 공포에 걸리지 않도록 주의해야 해요. (E)\'공허의 분비물\'을 발밑에 뿌려 접근하는 적의 이동 속도를 늦추며 대응하세요.', lv6: '(R)\'피해망상\'으로 시야가 사라진 뒤 돌격해오면 (E)\'공허의 분비물\'로 둔화시키며 거리를 벌리세요. 적의 체력이 낮아진 시점에 (R)\'살아있는 곡사포\'를 발사해 마무리 피해를 입히며 압박하세요. 라인을 타워 근처로 당겨서 정글의 개입이나 갑작스러운 진입에 대비해야 해요.', item: '판금 장화와 구인수의 격노검을 추천해요. 판금 장화로 기본 공격 피해를 줄이고 구인수의 격노검으로 (W)\'생체마법 폭격\'의 추가 피해를 더 자주 입혀요.', spell: '점멸과 회복을 추천해요. (E)\'말할 수 없는 공포\'의 연결이 완료되기 전에 점멸로 거리를 벌려 공포를 피하고 회복으로 유지력을 높여요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\'이 쌓일수록 평타와 스킬이 강해지니 1~2레벨에 붙지 않도록 조심하세요. (Q)\'부식성 침\'을 사용하여 멀리서 방어력을 낮추며 미리 체력을 깎아두는 것이 좋아요. (Q)\'학살\'의 도끼날 범위에 맞지 않도록 거리 조절을 하며 대응하세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘린 뒤 다리우스가 (E)\'포획\'을 쓰기 전까지 거리를 유지하세요. 다리우스의 (E)\'포획\'이 빠진 것을 보고 (Q)\'부식성 침\'과 평타로 공격을 이어가세요. (W)\'마비의 일격\'에 맞아 이동 속도가 느려지면 (E)\'공허의 분비물\'을 사용해 거리를 벌리세요.', lv6: '(R)\'살아있는 곡사포\'로 멀리서 다리우스의 체력을 깎아두면 처치하기 쉬워져요. 다리우스의 (R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 많을수록 아프니 체력이 낮을 때 근처에 머물지 마세요. 라인을 밀어 넣으며 다리우스의 (E)\'포획\'이 빠진 타이밍에 정글러와 함께 싸우세요.', item: '구인수의 격노검을 첫 코어로 올려 공격 속도를 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 정화를 추천해요. 정화로 (W)\'마비의 일격\'과 (E)\'포획\' 이후의 둔화를 풀 수 있고, 점멸로 (E)\'포획\' 사거리 밖으로 미리 벗어날 수 있어요.' },
    '라이즈': { lv1: '라이즈의 (Q)\'과부하\'는 첫 번째 맞는 적에게 피해를 주니 미니언 뒤에 서서 피해를 최소화하세요. 라이즈가 (E)\'주문 전이\'를 쓰기 전에는 거리를 유지하며 평타로 견제해요. 코그모는 초반에 체력 관리에 집중하며 라이즈가 스킬을 낭비하도록 유도하세요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'을 맞으면 속박되니 주의하며 거리를 조절하세요. 라이즈의 (W)\'룬 감옥\'이 빠진 타이밍에 (W)\'생체마법 폭격\'을 켜고 평타로 공격을 이어가세요. (Q)\'부식성 침\'을 맞춰 라이즈의 방어력을 낮추며 딜교환을 진행해요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용해 위치를 옮기면 정글러의 합류 가능성이 높으니 라인을 무리하게 밀지 마세요. 코그모는 (R)\'살아있는 곡사포\'로 멀리서 라이즈를 드러내고 체력이 낮은 라이즈를 마무리할 수 있어요. 라이즈의 스킬 연계에 묶이지 않도록 주의하며 (E)\'공허의 분비물\'로 접근을 늦추세요.', item: '구인수의 격노검을 첫 코어로 선택해 공격 속도를 높이세요. 신발은 라이즈의 마법 피해를 줄이고 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 라이즈의 속박을 피하거나 킬각을 잡는 데 도움이 돼요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 사용해 근접한 적에게 마법 피해를 입혀요. (Q)\'부식성 침\'을 활용해 럼블이 다가오기 전에 멀리서 견제하며 거리를 유지하세요. 럼블이 (E)\'전기 작살\'로 둔화를 걸기 전에 미리 거리를 벌리는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘린 뒤 럼블의 (W)\'고철 방패\'가 빠진 타이밍을 노려 딜교환을 하세요. 럼블이 (E)\'전기 작살\'을 맞히면 이동 속도가 줄어드니 럼블의 스킬을 피하며 (Q)\'부식성 침\'으로 방어력을 깎으세요. 럼블의 열기가 높아 위험 상태가 되면 (Q)\'화염방사기\'의 피해가 커지니 주의해야 해요.', lv6: '(R)\'이퀄라이저 미사일\'이 깔리면 궤적 안에서 피해를 입고 둔화되니 즉시 장판 밖으로 피하세요. 럼블이 궁극기를 사용한 뒤 빈틈이 생겼을 때 (R)\'살아있는 곡사포\'를 사용하여 체력이 낮은 럼블을 공격하세요. 라인을 밀어 넣을 때는 럼블의 궁극기와 정글러의 개입에 대비해 항상 시야를 확보해야 해요.', item: '마법사의 최후를 첫 코어로 가서 마법 저항력과 공격 속도를 챙기세요. 신발은 럼블의 마법 피해를 견디고 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 럼블은 (W)\'고철 방패\'와 (E)\'전기 작살\'로 교환을 이어가니 점화의 마무리 피해로 체력이 낮아진 럼블을 끝내기 좋아요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 압박하니 1~2레벨에는 최대한 거리를 유지하세요. (Q)\'부식성 침\'을 사용하여 레넥톤의 방어력을 낮추면서 멀리서 견제하는 것이 중요해요. 레넥톤이 (E)\'자르고 토막내기\'로 순식간에 붙지 못하도록 조심하며 플레이해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 (Q)\'부식성 침\'과 함께 지속적인 피해를 줘요. 레넥톤이 (E)\'자르고 토막내기\'로 진입할 때 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추세요. 분노가 쌓인 레넥톤의 (W)\'무자비한 포식자\' 기절에 걸리지 않도록 거리를 조절해요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력이 늘어나면 정면 교전을 피하고 거리를 벌리세요. 체력이 낮은 레넥톤에게 (R)\'살아있는 곡사포\'를 맞히면 큰 피해를 입히며 마무리할 수 있어요. 몸이 약해 위험하니 라인을 너무 밀지 말고 정글의 개입에 대비해요.', item: '구인수의 격노검을 첫 코어로 가서 공격 속도와 지속 피해를 높여요. 신발은 레넥톤의 물리 피해를 줄이는 판금 장화를 신어요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 줄이고 킬을 노려요.' },
    '렝가': { lv1: '(Q)\'부식성 침\'을 사용하여 적의 방어력을 낮추며 거리를 유지하세요. 렝가가 수풀에서 (P)\'보이지 않는 포식자\'를 활용해 접근하지 못하도록 주의하며 미니언을 챙겨야 해요.', lv3: '렝가의 (E)\'올가미 투척\'을 피하며 (E)\'공허의 분비물\'로 둔화를 걸어 거리를 벌리세요. (W)\'생체마법 폭격\'을 켜고 (Q)\'부식성 침\'으로 방어력을 낮춘 뒤 적절한 거리를 유지하며 지속적인 피해를 입혀야 해요.', lv6: '렝가가 (R)\'사냥의 전율\'로 위장 상태가 되면 (R)\'살아있는 곡사포\'로도 드러나지 않으니 포탑 쪽으로 물러나 기습에 대비하세요. 렝가가 도약해 들어온 뒤에는 (E)\'공허의 분비물\'로 둔화를 걸어 거리를 벌리고, 체력이 낮아진 렝가는 (R)\'살아있는 곡사포\'로 마무리하세요.', item: '판금 장화와 구인수의 격노검을 선택하세요. 렝가의 기본 공격 피해를 줄이고 공격 속도를 높여 지속적인 피해를 입히기 위해서예요.', spell: '점멸과 탈진을 추천해요. 렝가가 도약하여 들어올 때 탈진을 사용하여 피해량을 줄이고 점멸로 거리를 벌려야 해요.' },
    '리븐': { lv1: '리븐이 (Q)\'부러진 날개\'로 돌진하며 (P)\'룬 검\' 추가 피해를 입히려고 할 때 거리를 유지하며 (Q)\'부식성 침\'으로 견제하세요. 1~2레벨에는 리븐의 돌진 사거리 밖에서 최대한 평타로 압박하며 체력을 깎아두는 것이 좋아요. 리븐이 (Q)\'부러진 날개\'를 사용해 들어오는 타이밍을 주의하며 최대한 멀리 떨어져서 미니언을 받아먹으세요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 맞지 않도록 조심하면서 (W)\'생체마법 폭격\'을 켜고 긴 사거리를 활용해 딜교환을 하세요. 리븐이 (E)\'용맹\' 보호막을 사용해 피해를 흡수할 때는 무리하게 싸우지 말고 (E)\'공허의 분비물\'로 이동 속도를 늦추며 거리를 벌리세요. 리븐의 (Q)\'부러진 날개\' 마지막 타격은 주위 적을 공중으로 띄우니 그 범위 안에 서지 않게 위치를 잡아야 해요.', lv6: '리븐이 (R)\'추방자의 검\'을 사용하여 사거리가 길어지면 매우 위험하니 (R)\'살아있는 곡사포\'로 체력을 깎으며 거리를 두세요. 리븐이 들어올 때 (E)\'공허의 분비물\'을 깔아두면 리븐의 접근을 둔화로 방해하며 (R)\'살아있는 곡사포\'로 마무리 각을 볼 수 있어요. 리븐의 진입이 예상될 때는 정글러의 위치를 확인하며 라인을 너무 깊게 밀지 않도록 조심하세요.', item: '구인수의 격노검을 첫 코어로 올려서 공격 속도를 확보하세요. 신발은 기본 공격으로 받는 피해량을 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 리븐의 체력이 낮을 때 점화로 마무리하여 빠르게 처치하세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'으로 멀리서 둔화를 걸며 견제해요. 코그모는 (Q)\'부식성 침\'을 활용해 방어력을 깎으며 최대한 거리를 유지하세요. (Q)\'얼음 파편\'은 미니언을 꿰뚫고 지나가니 옆으로 비켜서서 피해를 받지 않도록 하세요.', lv3: '리산드라가 (W)\'서릿발\'로 속박하는 범위 안에 들어가지 않도록 거리를 지키세요. (W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 리산드라의 (E)\'얼음갈퀴 길\'이 빠진 뒤에 공격을 시작하세요. 상대의 진입을 막기 위해 (E)\'공허의 분비물\'을 미리 깔아두는 것도 좋아요.', lv6: '리산드라가 (R)\'얼음 무덤\'을 사용해 코그모에게 기절을 걸면 대응하기 어려우니 라인을 최대한 당겨서 관리하세요. (R)\'살아있는 곡사포\'를 사용하여 리산드라가 들어오는 것을 확인하고 (W)\'생체마법 폭격\'으로 대응하세요. 리산드라가 자신에게 궁극기를 써서 무적 상태가 되면 딜을 잠시 멈추고 다음을 준비하세요.', item: '첫 코어는 구인수의 격노검을 가서 공격 속도를 높이고 지속 딜을 강화하세요. 신발은 리산드라의 (W)\'서릿발\' 속박과 (R)\'얼음 무덤\' 기절 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. 리산드라의 (R)\'얼음 무덤\' 기절을 정화로 빠르게 풀고 거리를 벌릴 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 맞춰 마스터 이의 방어력을 낮추고 사거리 차이를 살려 평타로 계속 괴롭히세요. 마스터 이가 근접하면 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추며 거리를 벌리세요. 평타가 몇 번 이어지면 (P)\'2연속 공격\'이 터지니 붙은 채로 평타를 주고받지 마세요.', lv3: '(W)\'생체마법 폭격\'과 (Q)\'부식성 침\'이 모두 준비되면 긴 사거리로 딜교환을 시도하세요. 마스터 이가 (Q)\'일격 필살\'로 돌진해올 때는 (E)\'공허의 분비물\'을 발밑에 깔아 이동을 방해해야 해요. 마스터 이가 (W)\'명상\'을 사용하여 체력을 회복할 때는 무리하게 공격하지 말고 뒤로 물러나세요.', lv6: '(R)\'살아있는 곡사포\'를 사용하여 멀리서 마스터 이의 체력을 깎으며 압박하세요. 마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화 면역이 되니 (E)\'공허의 분비물\'보다는 거리를 벌리는 데 집중해야 해요. 마스터 이가 (Q)\'일격 필살\'로 대상이 되지 않는 순간에 갑자기 들어오는 것을 조심하세요.', item: '첫 코어 아이템으로 구인수의 격노검을 가서 공격 속도를 확보하세요. 신발은 공격 속도를 높여주는 광전사의 군화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 점화로 억제하며 처치할 수 있어요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 밀어내며 둔화를 걸고 (P)\'마법 흡수\'로 회복하며 다가와요. (Q)\'부식성 침\'을 사용하여 마오카이의 방어력을 낮추며 사거리 밖에서 지속적으로 견제하세요. 마오카이가 (Q)\'덤불 주먹\'을 사용하기 어렵도록 거리를 유지하며 미니언을 챙겨요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 도약해 속박하려 할 때 (E)\'공허의 분비물\'을 깔아 접근을 늦추세요. (W)\'뒤틀린 전진\'이 빠진 것을 확인한 뒤 (W)\'생체마법 폭격\'을 켜고 일방적인 공격을 이어가세요. (E)\'묘목 던지기\'가 설치된 수풀 근처로 들어가지 않도록 주의해요.', lv6: '(R)\'대자연의 마수\' 벽이 다가오면 옆으로 이동해 속박을 피하고 (R)\'살아있는 곡사포\'로 멀리서 피해를 입히세요. 마오카이가 진입할 때 (W)\'생체마법 폭격\'을 켜서 대응하며 체력이 낮은 적을 노리세요. 정글러의 개입을 방지하기 위해 라인을 너무 무리하게 밀지 마세요.', item: '헤르메스의 발걸음과 구인수의 격노검을 추천해요. 마오카이의 마법 피해를 줄이고 (W)\'생체마법 폭격\'의 효율을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 마오카이가 (P)\'마법 흡수\'로 체력을 회복하는 것을 억제하며 킬을 내기 위해서예요.' },
    '말자하': { lv1: '말자하가 (P)\'공허 태세\'를 켜고 있으면 피해가 크게 줄어드니 (Q)\'부식성 침\'으로 먼저 맞혀서 보호를 깨뜨리세요. 말자하가 (Q)\'공허의 부름\'을 쓰려고 하면 거리를 벌려 피해를 피하고 평타로 견제하세요. 1~2레벨에는 코그모의 사거리를 활용해 말자하를 압박하는 것이 좋아요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 공허충 때문에 딜교가 어려워지니 조심하세요. (W)\'생체마법 폭격\'을 사용하여 늘어난 사거리로 말자하의 (Q)\'공허의 부름\'을 피하며 공격하세요. 말자하가 (E)\'재앙의 환상\'을 유지하며 다가올 때는 거리를 벌려야 해요.', lv6: '말자하가 (R)\'황천의 손아귀\'로 제압을 걸면 아무것도 할 수 없으니 주의해서 움직이세요. 제압은 정화로 풀 수 없으므로 상대의 궁극기가 빠진 것을 확인한 뒤에 (R)\'살아있는 곡사포\'로 마무리하세요. 말자하가 (E)\'재앙의 환상\'으로 미니언을 처형하며 라인을 밀면 포탑 근처에서 파밍하며 버티세요.', item: '구인수의 격노검을 첫 코어 아이템으로 올려 공격 속도와 지속 피해를 챙기세요. 신발은 말자하의 마법 피해와 군중 제어 시간을 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 정화로 (Q)\'공허의 부름\'의 침묵을 풀 수 있어요. (R)\'황천의 손아귀\' 제압은 정화로 풀리지 않으니 사거리 밖에서 거리를 유지하세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 이동 속도를 훔쳐 압박해요. (Q)\'부식성 침\'으로 방어력을 낮추며 평타로 방패를 먼저 제거하는 것이 중요해요. 방패가 재생성되기 전에 꾸준히 공격하여 말파이트가 안정적으로 버티지 못하게 하세요.', lv3: '말파이트가 (E)\'지면 강타\'로 공격 속도를 낮추니 그 범위 안에서는 무리하게 평타를 치지 마세요. 말파이트의 (Q)\'지진의 파편\'은 대상 지정이라 걸어서 피할 수 없으니 (W)\'생체마법 폭격\'으로 꾸준히 피해를 입히며 체력을 관리하세요. (W)\'천둥소리\'로 강화된 평타와 여진이 들어오는 동안에는 잠시 물러나 거리를 두세요.', lv6: '말파이트의 (R)\'멈출 수 없는 힘\'은 저지 불가 상태로 돌진해 공중으로 띄우니 주의가 필요해요. 궁극기를 맞으면 스킬을 쓸 수 없으므로 정글러가 근처에 있을 때는 거리 조절을 철저히 하세요. 말파이트가 궁극기를 사용한 직후에는 (R)\'살아있는 곡사포\'와 (W)\'생체마법 폭격\'을 사용하여 멀리서 화력을 쏟아부으세요.', item: '첫 코어로 몰락한 왕의 검을 선택해 체력이 높은 말파이트를 효율적으로 공격하세요. 신발은 말파이트의 마법 피해를 줄이고 (Q)\'지진의 파편\' 둔화 시간을 줄이기 위해 헤르메스의 발걸음을 신어요.', spell: '점멸과 정화를 추천해요. 정화로 (Q)\'지진의 파편\' 둔화를 풀 수 있지만 (R)\'멈출 수 없는 힘\'의 띄우기는 풀 수 없으니 점멸로 미리 거리를 두세요.' },
    '모데카이저': { lv1: '1~2레벨에는 (Q)\'부식성 침\'으로 계속 견제하며 거리를 벌리세요. 모데카이저의 (Q)\'말살\'은 단일 대상에게 맞으면 피해가 크니 미니언 근처에서 옆으로 피해 주세요. (P)\'암흑 탄생\' 오라가 켜지기 전에 짧게 공격하고 물러나는 것이 중요해요.', lv3: '(E)\'죽음의 손아귀\'에 끌려가면 (Q)\'말살\' 연계에 노출되니 사거리 밖에서 주의하세요. (E)\'죽음의 손아귀\'가 빠진 것을 확인하고 (W)\'생체마법 폭격\'을 켜서 최대 체력 비례 피해로 압박하세요. 모데카이저가 다가오면 (E)\'공허의 분비물\'로 둔화를 걸어 거리 조절을 하세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 수은 장식띠나 순간이동으로 빠져나갈 수 없으니 끌려가기 전에 (R)\'살아있는 곡사포\'로 최대한 체력을 깎아두세요. 궁극기 안에서는 (W)\'생체마법 폭격\'의 사거리를 이용해 최대한 멀리서 때리세요. 정글러가 와도 (R)\'죽음의 세계\' 안으로는 들어올 수 없으니 스스로 살아남아야 해요.', item: '구인수의 격노검을 첫 코어로 선택해 (W)\'생체마법 폭격\'의 최대 체력 비례 피해를 더 자주 입히세요. 신발은 마법 저항력을 높이고 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'의 체력 회복 효과를 점화로 줄여야 마무리 피해를 입히기 편해요.' },
    '문도박사': { lv1: '문도 박사가 (Q)\'오염된 뼈톱\'을 던지면 미니언 뒤에 서서 맞지 않도록 조심하세요. (Q)\'부식성 침\'으로 문도 박사의 방어력을 낮추며 원거리에서 계속 공격하세요. 뼈톱이 챔피언에게 맞으면 문도 박사가 체력을 회복하니 뼈톱만 피해도 소모전을 길게 끌고 갈 수 있어요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 문도 박사의 최대 체력에 비례한 마법 피해를 입히세요. 문도 박사가 (W)\'심장 전기 충격\'을 켜고 다가오면 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추며 거리를 벌리세요. (Q)\'부식성 침\'을 맞힌 뒤에는 문도 박사가 (W)\'심장 전기 충격\'을 터뜨리기 전에 빠르게 거리를 유지하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력이 급격히 회복되고 이동 속도도 빨라지니 억지로 싸우지 마세요. (R)\'살아있는 곡사포\'를 활용해 문도 박사의 체력이 낮아진 시점에 강력한 마법 피해를 입혀 처치하세요. 문도 박사가 궁극기를 사용한 뒤에는 라인을 관리하며 정글러의 개입에 대비하세요.', item: '구인수의 격노검을 첫 코어로 올려서 공격 속도와 지속 피해를 극대화하세요. 신발은 문도 박사의 마법 피해를 줄여주는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 문도 박사의 회복 효과를 감소시켜야 확실하게 킬을 노릴 수 있어요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 조준하여 멀리서 견제할 수 있으니 거리를 잘 조절해야 해요. (Q)\'부식성 침\'을 맞히면 상대의 방어력을 낮출 수 있으니 이를 활용해 짧게 교환하세요. 초반에는 무리하게 맞대결하기보다 미니언을 챙기며 기회를 보세요.', lv3: '(W)\'생체마법 폭격\'을 켜고 사거리가 늘어난 상태에서 최대한 멀리서 공격하세요. 바루스의 (Q)\'꿰뚫는 화살\'이 빠진 것을 확인하고 (E)\'공허의 분비물\'로 이동 속도를 늦추며 공격하세요. 바루스의 (E)\'퍼붓는 화살\'이 땅에 깔리면 그 위를 피하며 공격을 이어가세요.', lv6: '바루스의 (R)\'부패의 사슬\'에 맞으면 이동이 차단되어 위험하니 항상 조심해야 해요. (R)\'살아있는 곡사포\'를 사용해 멀리서 체력이 낮은 바루스를 저격하거나 위치를 확인하세요. 정글러가 오면 (E)\'공허의 분비물\'로 진액을 남겨 바루스의 접근을 방해하세요.', item: '구인수의 격노검을 첫 코어로 가면 (W)\'생체마법 폭격\'의 효과를 극대화하기 좋아요. 신발은 공격 속도를 높여주는 광전사의 군화로 선택하세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 스킬을 피하며 거리를 조절하기 좋아요.' },
    '베인': { lv1: '베인이 (W)\'은화살\'로 고정 피해를 입히지 못하게 거리 조절을 하세요. (Q)\'부식성 침\'으로 먼저 방어력을 낮추며 견제하고, 베인의 (Q)\'구르기\' 사거리 밖에서 싸우는 것이 좋아요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 확보하고 베인이 (Q)\'구르기\'로 접근하기 전에 딜을 넣으세요. 베인의 (E)\'선고\'는 맞은 대상을 뒤로 날려 지형에 부딪히면 기절시키니 벽 근처에서는 위치를 잡지 마세요. 베인이 붙으면 (E)\'공허의 분비물\'로 이동 속도를 늦추며 대응하세요.', lv6: '베인이 (R)\'결전의 시간\'을 켜고 (Q)\'구르기\'로 투명해지면 위치를 파악하기 어려워지니 조심하세요. (R)\'살아있는 곡사포\'는 은신하지 않은 대상만 드러내니 투명한 베인에게는 의지하지 말고 체력이 낮은 베인을 마무리하는 용도로 쓰세요. 베인이 투명해지면 무리하게 딜교환하지 말고 거리를 유지하세요.', item: '구인수의 격노검을 코어로 선택해 공격 속도를 높이세요. 신발은 베인의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 탈진으로 베인이 들어올 때 피해량을 감소시켜 생존력을 높이세요.' },
    '볼리베어': { lv1: '볼리베어가 (Q)\'번개 강타\'로 이동 속도를 높여 달려들며 기절을 시키니 거리를 잘 조절하세요. 1~2레벨에는 (Q)\'부식성 침\'을 사용하여 방어력을 낮추며 멀리서 견제하는 것이 좋아요. 볼리베어의 돌진에 맞지 않도록 주의하며 미니언을 정리하세요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 체력을 회복하지 못하도록 표식이 남은 상태에서 빠르게 거리를 벌리세요. (E)\'천공 분열\'은 지정한 위치에 번개가 떨어지니 표시된 범위에서 벗어나 둔화를 피하세요. (W)\'생체마법 폭격\'을 켜고 사거리 안에서 지속적인 피해를 입히는 것이 중요해요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 도약하여 포탑을 비활성화하며 다이브를 올 수 있으니 주의하세요. 체력이 낮아지면 (R)\'살아있는 곡사포\'로 멀리서 압박하며 볼리베어의 진입을 억제하세요. 볼리베어가 궁극기로 들어온 직후에는 (E)\'공허의 분비물\'로 둔화를 걸어 거리를 확보하는 것이 좋아요.', item: '판금 장화를 가서 물리 피해를 줄이세요. 구인수의 격노검을 첫 코어로 올려 공격 속도를 확보하세요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 회복하며 견제하는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (Q)\'부식성 침\'으로 방어력과 마법 저항력을 깎은 뒤 짧게 평타를 넣고 빠지는 식으로 견제해 주세요. (Q)\'수혈\'을 두 번 쓴 뒤에는 강화된 (Q)\'수혈\'이 준비되니 그때는 사거리 안에 들어가지 마세요.', lv3: '(W)\'생체마법 폭격\'의 최대 체력 비례 피해를 체력이 높은 블라디미르에게 평타로 꾸준히 넣으세요. (E)\'선혈의 파도\'는 적 유닛이 가로막을 수 있으니 미니언 뒤에 서서 피해를 줄이세요. 블라디미르가 (W)\'피의 웅덩이\'로 변해 공격 대상이 되지 않을 때는 스킬을 아꼈다가 웅덩이가 끝나는 시점에 (E)\'공허의 분비물\'을 써서 둔화시키세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니, 궁극기 범위에 들어갔다면 무리하게 싸우지 말고 뒤로 빠지세요. 블라디미르의 체력이 낮아지면 (R)\'살아있는 곡사포\'로 멀리서 안전하게 마무리 피해를 입히세요. 정글러가 올 때까지 라인을 당기며 (Q)\'부식성 침\'으로 체력을 갉아먹는 운영을 하세요.', item: '구인수의 격노검과 헤르메스의 발걸음을 추천해요. 구인수의 격노검은 (W)\'생체마법 폭격\'의 효과를 더 자주 발동시켜 체력이 높은 상대를 효율적으로 깎고, 헤르메스의 발걸음은 마법 저항력과 강인함을 제공해요.', spell: '점멸과 점화를 추천해요. 블라디미르는 (Q)\'수혈\'을 통해 계속 체력을 회복하므로 점화의 치유 감소 효과로 이를 억제해야 해요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 다가오지 못하게 (Q)\'부식성 침\'을 사용하여 거리를 유지하며 견제하세요. 뽀삐가 방패를 주워 보호막을 얻기 전에 평타로 먼저 압박하는 것이 좋아요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 사거리를 늘리고 멀리서 공격을 시작하세요. 뽀삐의 (E)\'용감한 돌진\'은 대상에게 돌진하는 스킬이라 걸어서 피하기 어려우니 빠진 것을 확인한 뒤에 딜교환을 하고 벽 근처에서는 위치를 잡지 마세요. 뽀삐가 (W)\'굳건한 태세\'를 켜면 이동 속도가 빨라지니 다가오는 속도를 보고 미리 거리를 벌리세요.', lv6: '(R)\'살아있는 곡사포\'를 사용하여 체력이 낮은 뽀삐를 멀리서 마무리하세요. 뽀삐가 (R)\'수호자의 심판\'을 사용할 때는 충전하는 동안 범위 밖으로 벗어나야 해요. 라인을 밀어 넣으며 정글러의 개입에 대비하세요.', item: '구인수의 격노검을 첫 코어 아이템으로 선택하여 공격 속도를 높이세요. 신발은 뽀삐의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 (Q)\'망치 강타\' 지대에서 빠르게 빠져나오고, 점멸로 벽에서 먼 쪽으로 거리를 벌려 (E)\'용감한 돌진\'의 기절을 대비해요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나 뒤의 적까지 맞히니 미니언 뒤로 피하지 마세요. (Q)\'부식성 침\'으로 방어력을 낮춘 뒤 평타로 견제하며 초반 압박을 견뎌내야 해요. 사이온이 (Q)\'대량 학살 강타\'를 충전하며 다가올 때는 미리 거리를 벌려두는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜고 사거리를 늘려 지속적으로 피해를 입히세요. 사이온이 (W)\'영혼의 용광로\'로 보호막을 씌우면 재시전 폭발 범위 밖에서 (Q)\'부식성 침\'으로 견제하며 기다리세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하며 다가오면 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추며 대응하세요.', lv6: '(R)\'살아있는 곡사포\'를 활용해 멀리서 체력이 낮은 사이온을 저격하며 압박하세요. 사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진하면 옆으로 비켜서서 충돌을 피하는 것이 핵심이에요. 사이온이 (P)\'영광스러운 죽음\'으로 되살아나더라도 (R)\'살아있는 곡사포\'로 마무리할 수 있으니 집중하세요.', item: '구인수의 격노검을 첫 코어로 올려서 (W)\'생체마법 폭격\'의 피해를 극대화하세요. 신발은 사이온의 기본 공격과 (Q)\'대량 학살 강타\'의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인을 밀어두고 합류하는 경우가 많으니 순간이동으로 라인 손해를 방지하세요.' },
    '사일러스': { lv1: '사일러스가 (Q)\'사슬 후려치기\'로 둔화시키며 다가올 때 (W)\'생체마법 폭격\'을 켜고 거리를 유지하세요. (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 평타로 견제하며 사일러스가 쉽게 붙지 못하게 해요.', lv3: '사일러스가 (W)\'국왕시해자\'로 들어오면 체력을 회복하니 돌진 범위 안에 서지 않게 거리를 유지하세요. 사일러스가 붙으면 (E)\'공허의 분비물\'을 발밑에 깔아 둔화시키고 물러나세요. (E)\'도주 / 억압\'의 사슬에 맞으면 사일러스가 내 쪽으로 날아와 공중에 띄우니 사슬이 날아올 때 옆으로 움직여 피해요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'살아있는 곡사포\'를 가져가면 원거리에서 폭발적인 피해를 줄 수 있으니 조심하세요. (R)\'살아있는 곡사포\'를 활용해 멀리서 사일러스의 체력을 미리 깎아두고, 사일러스가 들어올 공간을 주지 않도록 라인을 관리해요.', item: '구인수의 격노검을 첫 코어로 올려 공격 속도를 확보하세요. 신발은 마법 저항력을 높여주는 헤르메스의 발걸음을 선택해요.', spell: '점멸과 유체화를 추천해요. 유체화로 사일러스의 접근을 피해 거리를 벌리며 카이팅하세요.' },
    '세주아니': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 사용하여 최대한 멀리서 적을 견제하며 거리를 유지하세요. 세주아니가 (Q)\'혹한의 맹습\'으로 돌진해 들어오는 타이밍을 조심하며 최대한 안전하게 성장해야 해요.', lv3: '3레벨이 되면 (W)\'생체마법 폭격\'을 켜고 사거리를 확보하여 일방적으로 딜교환을 시도하세요. 세주아니의 (Q)\'혹한의 맹습\'을 먼저 빼도록 유도하며 (W)\'혹한의 서릿발\'에 맞지 않게 주의해야 해요.', lv6: '6레벨 이후에는 세주아니의 (R)\'빙하 감옥\'에 맞지 않도록 조심하며 (R)\'살아있는 곡사포\'로 체력이 낮은 적을 저격하세요. 정글러가 근처에 있다면 세주아니가 (E)\'만년 서리\'를 사용하기 전에 먼저 압박을 넣는 것이 좋아요.', item: '헤르메스의 발걸음과 구인수의 격노검을 선택해요. 세주아니의 다양한 군중 제어 효과에 대비하고 공격 속도를 빠르게 확보하기 위해서예요.', spell: '점멸과 정화를 사용해요. 세주아니의 기절이나 둔화 효과를 빠르게 풀고 도망치기 위해서예요.' },
    '세트': { lv1: '(Q)\'부식성 침\'으로 방어력을 깎으며 일방적으로 견제하세요. 세트가 (Q)\'주먹다짐\'을 켜고 빠르게 다가오면 뒤로 물러나 거리 조절에 집중하세요. 1~2레벨에는 짧은 딜교환만 하고 절대 붙지 마세요.', lv3: '(W)\'생체마법 폭격\'으로 사거리를 늘려 안전하게 최대 체력 비례 피해를 입히세요. 세트가 (E)\'안면 강타\'로 끌어당기려 하면 (E)\'공허의 분비물\'을 뱉어 이동 속도를 늦추고 거리를 벌리세요. (W)\'강펀치\'의 중심선에 맞지 않게 옆으로 피하는 것이 중요해요.', lv6: '(R)\'살아있는 곡사포\'로 멀리서 체력이 낮은 세트를 압박하며 킬각을 보세요. 세트의 (R)\'대미 장식\'에 붙잡혀 제압당하면 아무것도 할 수 없으니 정글러가 근처에 없을 때는 무리하게 붙지 마세요. 라인을 밀어두고 타워 근처에서 (R)\'살아있는 곡사포\'를 쏘며 안전하게 파밍하세요.', item: '구인수의 격노검을 가서 (W)\'생체마법 폭격\'의 효율을 극대화하고 빠른 공격 속도로 압박하세요. 신발은 세트의 평타 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 세트의 (E)\'안면 강타\' 사거리를 주지 않고 계속 거리를 벌릴 수 있어요.' },
    '쉔': { lv1: '쉔이 (Q)\'황혼 강습\'을 쓰러 다가오기 전에 (Q)\'부식성 침\'으로 방어력과 마법 저항력을 깎으세요. 쉔이 스킬을 써서 (P)\'기 보호막\'을 얻었을 때는 공격을 잠시 멈추고 보호막이 사라진 뒤에 다시 공격하세요. 첫 웨이브부터 거리 조절을 하며 쉔이 다가오지 못하게 압박하세요.', lv3: '(W)\'의지의 결계\'가 켜지면 평타 공격이 차단되니, 결계가 끝날 때까지 (E)\'공허의 분비물\'로 둔화만 시키며 거리를 벌리세요. 쉔이 (E)\'그림자 돌진\'으로 들어오면 도발 상태에서는 스킬을 쓸 수 없으니 돌진 전에 미리 거리를 확보하세요. (W)\'생체마법 폭격\'을 켜고 쉔의 (W)\'의지의 결계\'가 빠진 타이밍에 강하게 딜교환하세요.', lv6: '쉔이 (R)\'단결된 의지\'로 다른 라인에 합류하면 빠르게 라인을 밀어 포탑을 압박하세요. 쉔이 (E)\'그림자 돌진\'으로 진입하려 할 때 (R)\'살아있는 곡사포\'를 쏴서 체력을 깎고 거리를 유지하세요. 정글러가 함께 올 때는 쉔의 (E)\'그림자 돌진\'이 빠진 것을 확인한 뒤 (E)\'공허의 분비물\'로 둔화를 걸고 집중 공격하세요.', item: '구인수의 격노검을 가서 빠른 공격 속도와 추가 피해로 쉔의 체력을 깎으세요. 신발은 (E)\'그림자 돌진\'의 도발 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 쉔의 (E)\'그림자 돌진\' 도발에 걸렸을 때 정화로 빠르게 풀고 (E)\'공허의 분비물\'을 써서 도망치세요.' },
    '쉬바나': { lv1: '쉬바나의 (Q)\'잉걸불 일격\'으로 강화된 평타는 대상과 주변을 함께 때리니 붙어서 교환하지 마세요. (Q)\'부식성 침\'을 맞춰 상대의 방어력을 낮추고 평타로 계속 견제하는 것이 좋아요. (W)\'생체마법 폭격\'을 켜고 최대한 멀리서 공격하며 성장을 준비하세요.', lv3: '쉬바나가 (E)\'용암 분출\'을 사용하여 둔화를 거는 것을 주의하며 거리 조절을 하세요. (Q)\'부식성 침\'을 먼저 맞춘 뒤에 (W)\'생체마법 폭격\'의 지속 피해를 입히는 방식으로 딜교환을 해요. 상대의 (W)\'지옥불 방패\' 보호막이 빠진 뒤에 집중적으로 공격하면 좋아요.', lv6: '쉬바나가 (R)\'용의 강림\'을 사용하여 저지 불가 상태로 돌진해오면 대응하기 어려우니 조심하세요. (R)\'살아있는 곡사포\'를 사용하여 멀리서 체력이 낮은 적을 저격하며 킬각을 노려보세요. 상대가 용으로 변신해 들어올 때는 (E)\'공허의 분비물\'을 깔아 이동을 방해하며 거리를 유지하세요.', item: '판금 장화와 구인수의 격노검을 추천해요. 쉬바나의 기본 공격 피해를 줄이면서 공격 속도를 높여 (W)\'생체마법 폭격\'의 효율을 극대화하기 위해서예요.', spell: '점멸과 정화를 선택하세요. 정화로 (E)\'용암 분출\'의 둔화를 풀 수 있고, 점멸로 용 형상 쉬바나가 붙기 전에 거리를 벌릴 수 있어요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 멀리서 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. 코그모는 (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 (W)\'생체마법 폭격\'을 켜서 사거리를 확보하며 거리를 유지하세요. 초반에 (Q)\'죽음의 손길\'을 맞지 않으면서 지속적인 공격을 넣으면 앞서갈 수 있어요.', lv3: '스웨인이 (E)\'속박명령\'을 사용하면 파동이 돌아올 때 옆으로 움직여서 속박과 끌어당기기를 피해야 해요. (W)\'제국의 눈\'은 지정한 지역에 잠시 뒤 떨어지니 표시가 보이면 바로 벗어나 둔화를 피하세요. 스웨인의 (E)\'속박명령\'이 빠진 뒤에 (W)\'생체마법 폭격\'을 켜고 공격하면 딜교환을 수월하게 할 수 있어요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용하면 주변 적의 체력을 흡수하며 강해지니 무리하게 붙어서 싸우지 마세요. 코그모는 (R)\'살아있는 곡사포\'를 멀리서 발사해 피해를 입히며 스웨인의 (R)\'악의 승천\' 범위 밖에서 계속 카이팅해야 해요. 스웨인이 변신한 상태에서는 (E)\'공허의 분비물\'로 바닥을 둔화시키며 거리를 벌리는 것이 안전해요.', item: '구인수의 격노검을 첫 코어로 올려 공격 속도를 확보하세요. 신발은 스웨인의 마법 피해와 (E)\'속박명령\'의 제어 효과를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인이 (P)\'굶주린 새떼\'로 체력을 회복하는 것을 방해하며 킬을 노릴 수 있어요.' },
    '스카너': { lv1: '(Q)\'부식성 침\'을 사용하여 스카너의 방어력을 낮추며 거리를 유지하세요. 스카너가 (Q)\'부서진 대지/지반 돌출\'을 사용해 다가오려 하면 미니언 사이에서 거리를 벌리며 공격해요. 초반에는 스카너의 접근에 노출되지 않도록 주의하며 최대한 멀리서 딜을 넣으세요.', lv3: '스카너가 (W)\'대지의 수호자\'를 사용해 보호막을 얻으면 무리하게 싸우지 마세요. (W)\'생체마법 폭격\'을 켜고 (Q)\'부식성 침\'으로 방어력을 낮춘 뒤 긴 사거리를 활용해 공격해요. 스카너의 (E)\'이쉬탈의 격돌\'이 빠진 것을 확인한 뒤에 적극적으로 딜교환을 시도하세요.', lv6: '스카너의 (R)\'꿰뚫기\'는 제압 효과이므로 맞기 전에 거리를 벌려야 해요. (R)\'살아있는 곡사포\'를 사용해 체력이 낮은 스카너를 마무리하거나 위치를 드러내세요. (E)\'공허의 분비물\'을 깔아 스카너의 접근을 늦추며 정글러의 지원을 기다리세요.', item: '구인수의 격노검과 광전사의 군화를 선택하세요. 광전사의 군화로 공격 속도를 높이고 구인수의 격노검의 효과를 통해 (W)\'생체마법 폭격\'의 피해를 극대화하기 위해서예요.', spell: '점멸과 유체화를 추천해요. 스카너의 (E)\'이쉬탈의 격돌\'과 (Q)\'부서진 대지/지반 돌출\'로부터 거리를 벌리기 위해서예요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 남기며 다가오면 독구름 위에서는 싸우지 마세요. (Q)\'부식성 침\'을 사용해 신지드의 방어력을 낮추고 최대한 멀리서 평타로 견제하세요. 신지드가 근처로 붙으려 하면 거리를 유지하며 독구름을 피하는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 공격 사거리를 늘리고 신지드를 멀리서 공격하세요. 신지드가 던지는 (W)\'초강력 접착제\'를 밟으면 둔화되고 이동 스킬을 쓸 수 없으니 주의해야 해요. (E)\'던져넘기기\'에 맞지 않도록 위치를 잡고 신지드의 (W)\'초강력 접착제\'가 빠진 타이밍에 (Q)\'부식성 침\'으로 딜교환을 하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 (Q)\'맹독의 자취\'로 고통스러운 상처를 남기니 독구름을 피하며 싸우세요. (R)\'살아있는 곡사포\'로 멀리서 신지드의 체력을 깎아두면 나중에 처치하기 쉬워요. 신지드가 (E)\'던져넘기기\'를 사용해 접근할 때는 (W)\'생체마법 폭격\'의 사거리를 활용해 거리를 벌리세요.', item: '공격 속도를 높여주는 구인수의 격노검을 첫 코어로 가세요. 신지드의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (W)\'초강력 접착제\'의 둔화나 던져진 뒤의 속박을 정화로 풀 수 있어요.' },
    '신짜오': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 사용하여 멀리서 적의 방어력을 낮추며 견제해요. 신 짜오가 (E)\'무쌍돌격\'으로 달려들면 최대한 뒤로 물러나며 거리를 유지하세요. 초반에 무리하게 맞서기보다 적의 접근을 막는 것에 집중해요.', lv3: '(W)\'생체마법 폭격\'을 켜고 (E)\'공허의 분비물\'을 사용하여 신 짜오의 접근을 늦춰요. 상대의 (Q)\'삼조격\'에 의한 에어본을 조심하며 (Q)\'부식성 침\'으로 방어력을 낮춘 뒤 공격하세요. (E)\'공허의 분비물\'이 지나가는 길목에 적을 두어 둔화를 유도해요.', lv6: '(R)\'살아있는 곡사포\'를 사용하여 멀리서 적의 체력을 깎으며 교전을 준비해요. 신 짜오가 (R)\'현월수호\'를 사용해 원거리 공격을 차단하면 무리하게 진입하지 말고 거리를 벌리세요. 정글러가 근처에 있다면 (E)\'공허의 분비물\'을 활용하여 적의 진입을 방해하며 싸워요.', item: '판금 장화와 구인수의 격노검을 선택해요. 상대의 물리 피해를 줄이고 공격 속도를 높여 (W)\'생체마법 폭격\'의 피해를 높여요.', spell: '점멸과 유체화를 선택해요. 신 짜오의 돌진을 피하거나 거리를 벌리는 데 도움을 줘요.' },
    '아이번': { lv1: '(Q)\'부식성 침\'을 사용하여 아이번의 저항력을 낮추며 원거리에서 계속 괴롭혀요. (Q)\'덩굴뿌리\'에 맞으면 이동이 제한되니 무빙으로 피하며 첫 웨이브를 압박하세요. 상대의 사거리 밖에서 평타 견제를 이어가는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 최대 체력 비례 피해로 강하게 압박하세요. (Q)\'덩굴뿌리\'가 빠진 것을 확인한 뒤 딜교환을 시도하고, 상대가 (E)\'보호의 씨앗\'으로 버티면 (E)\'공허의 분비물\'로 둔화시켜 거리를 벌리세요. 무리하게 진입하지 말고 긴 사거리로 계속 갉아먹으세요.', lv6: '(R)\'데이지!\'가 소환되면 데이지의 공격 범위 밖에서 (R)\'살아있는 곡사포\'로 아이번을 저격하세요. 데이지의 연속 공격으로 인한 공중으로 띄우기 효과를 조심하며 (E)\'공허의 분비물\'로 접근을 늦추세요. 정글러 개입을 고려해 라인을 적절히 유지하며 상대 체력을 깎으세요.', item: '구인수의 격노검과 헤르메스의 발걸음을 선택하세요. 구인수의 격노검은 (W)\'생체마법 폭격\'의 효율을 높여주며, 헤르메스의 발걸음은 마법 저항력과 강인함을 제공해 (Q)\'덩굴뿌리\'의 속박 지속시간을 줄여줘요.', spell: '점멸과 정화를 추천해요. (Q)\'덩굴뿌리\'의 속박으로 인해 이동이 막혔을 때 정화로 즉시 풀고 위치를 옮겨 적의 후속 접근이나 정글러의 갱킹에서 벗어나야 해요.' },
    '아지르': { lv1: '1~2레벨에는 아지르의 (Q)\'사막의 맹습\' 견제를 조심하며 거리를 유지하세요. (Q)\'부식성 침\'을 사용하여 방어력을 낮추고 공격 속도를 확보하며 미니언을 챙겨요. (E)\'공허의 분비물\'을 바닥에 깔아두면 아지르가 접근할 때 둔화 효과를 줄 수 있어요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 사거리를 늘리고 아지르를 멀리서 공격하세요. 아지르의 (E)\'신기루\' 돌진을 경계하며 (E)\'공허의 분비물\'로 상대의 이동 경로를 방해해요. 상대의 (Q)\'사막의 맹습\'을 피하면서 꾸준히 평타를 섞어주는 것이 중요해요.', lv6: '(R)\'살아있는 곡사포\'를 사용해 멀리서 아지르의 체력을 깎으며 압박하세요. 아지르가 (R)\'황제의 진영\'으로 거리를 벌리려 할 때를 대비해 위치를 잘 잡아야 해요. 체력이 낮은 적에게 더 큰 피해를 주는 (R)\'살아있는 곡사포\'로 킬을 노려보세요.', item: '헤르메스의 발걸음과 구인수의 격노검을 가요. 아지르의 마법 피해를 견디기 위해 헤르메스의 발걸음을 선택해요. 구인수의 격노검으로 공격 속도를 높여요.', spell: '점멸과 유체화를 추천해요. 아지르와의 거리 조절을 하며 지속적으로 공격을 이어가기 위해서예요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 둔화를 걸며 견제하니 거리를 유지하세요. (Q)\'부식성 침\'을 맞춰서 방어력과 마법 저항력을 낮추고 공격 속도를 높여서 받아치세요. 아칼리가 스킬을 맞힌 뒤 (P)\'암살자의 표식\' 원 밖으로 나가면 다음 평타의 사거리와 피해가 늘어나니 그 순간에는 뒤로 물러나세요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남기며 돌진할 때 (E)\'공허의 분비물\'을 깔아서 이동 속도를 늦추세요. 아칼리가 (W)\'황혼의 장막\' 안에 있으면 평타로는 대상을 지정할 수 없으니 연막 쪽으로 (E)\'공허의 분비물\'이나 (Q)\'부식성 침\'을 던져 맞히세요. (Q)\'부식성 침\'으로 아칼리의 방어력을 깎으며 거리를 조절하세요.', lv6: '아칼리가 (R)\'무결처형\'으로 돌진하면 (R)\'살아있는 곡사포\'로 피해를 입히세요. (W)\'황혼의 장막\' 안에 숨은 아칼리는 위치를 알 수 없으니 연막이 사라질 때까지 조심하세요. 아칼리가 궁극기로 두 번 돌진하며 체력이 낮은 당신을 노릴 때 빠르게 대응하세요.', item: '구인수의 격노검을 먼저 올려서 공격 속도를 확보하세요. 신발은 아칼리의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진을 사용하면 아칼리의 피해량을 줄이고 이동 속도를 늦출 수 있어요.' },
    '아크샨': { lv1: '아크샨의 (Q)\'복수의 부메랑\' 견제를 주의하며 최대한 거리를 유지해요. (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 평타로 압박하세요. 아크샨이 (P)\'비열한 싸움\'으로 보호막을 얻지 못하게 조심하며 대응해요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 사거리를 확보하는 것이 매우 중요해요. 아크샨이 (E)\'영웅의 비상\'으로 진입하려 하면 (E)\'공허의 분비물\'을 사용하여 둔화를 걸어주세요. 아크샨의 (Q)\'복수의 부메랑\'을 피하면서 긴 사거리를 활용해 딜교환을 시도하세요.', lv6: '(R)\'살아있는 곡사포\'를 활용해 체력이 낮은 아크샨을 멀리서 저격하며 킬각을 노려보세요. 아크샨의 (R)\'인과응보\'는 잃은 체력에 비례한 피해라 체력이 낮을 때는 조심해야 해요. 아크샨이 (E)\'영웅의 비상\'으로 지형을 넘어올 수 있으니 시야를 확보하고 정글러의 위치를 확인하세요.', item: '광전사의 군화와 구인수의 격노검을 선택해요. 공격 속도를 높여서 지속적인 피해를 주는 것이 핵심이에요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 (Q)\'복수의 부메랑\'을 피하고 거리를 유지해요.' },
    '아트록스': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 사용하여 최대한 멀리서 견제하세요. 아트록스의 (Q)\'다르킨의 검\' 끝자락에 맞으면 공중에 띄워지니 무빙으로 계속 피하며 거리를 유지하세요. (P)\'사신 태세\'가 활성화된 평타는 체력을 회복하므로 무리한 평타 교환은 피하세요.', lv3: '(W)\'지옥사슬\'에 맞으면 빠르게 범위를 벗어나 중앙으로 끌려가는 피해를 막으세요. (E)\'파멸의 돌진\'으로 거리를 좁히려 할 때 (E)\'공허의 분비물\'을 발밑에 깔아 둔화시키며 거리를 벌리세요. (W)\'생체마법 폭격\'을 켜고 긴 사거리로 일방적인 딜교환을 하며 (Q)\'다르킨의 검\' 쿨타임을 빼는 것이 중요해요.', lv6: '(R)\'세계의 종결자\'를 사용한 아트록스는 회복량과 이동 속도가 크게 늘어나니 정면에서 싸우지 말고 뒤로 물러나세요. 아트록스의 궁극기 지속 시간이 끝나갈 때 (R)\'살아있는 곡사포\'를 여러 번 맞춰 체력을 깎고 킬각을 보세요. 정글러의 개입이 쉽도록 라인을 당기고 (E)\'공허의 분비물\'로 적을 늦추세요.', item: '구인수의 격노검을 첫 코어로 가서 (W)\'생체마법 폭격\'의 체력 비례 피해를 극대화하세요. 신발은 아트록스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 아트록스는 (E)\'파멸의 돌진\'과 (R)\'세계의 종결자\'로 회복하는 양이 많아 점화의 치유 감소 효과가 매우 중요해요.' },
    '암베사': { lv1: '(Q)\'부식성 침\'으로 계속 견제하며 거리를 유지하세요. 암베사가 (Q)\'교활한 휩쓸기\'를 쓰며 (P)\'용사냥개의 발걸음\'으로 진입하려고 하면 뒤로 물러나세요. 최대한 평타 사거리를 이용해 일방적으로 공격하는 게 좋아요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 (E)\'공허의 분비물\'로 이동 속도를 늦춰 접근을 막으세요. 암베사가 (W)\'배척\'을 준비하는 동안 피해를 주면 내려칠 때의 피해량이 커지니 잠시 공격을 멈추세요. (W)\'배척\'이 끝난 뒤 다시 (Q)\'부식성 침\'으로 딜교환하세요.', lv6: '(R)\'살아있는 곡사포\'로 아주 멀리서 체력을 깎아 킬각을 보세요. (R)\'공개 처형\'은 저지 불가 상태로 먼 거리를 순간 이동해 제압하니 체력이 낮을 때는 포탑 근처에서 라인을 받으세요. 제압 상태에서는 어떤 스킬도 쓸 수 없으니 궁극기가 빠진 것을 확인한 뒤에 딜교환을 이어가세요.', item: '구인수의 격노검을 첫 코어로 가서 (W)\'생체마법 폭격\'의 최대 체력 비례 피해를 극대화하세요. 신발은 암베사의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. (P)\'용사냥개의 발걸음\'으로 계속 파고드는 암베사를 상대로 거리 조절을 하며 카이팅하기 좋아요.' },
    '애니비아': { lv1: '애니비아의 (Q)\'냉기 폭발\'은 투사체 경로에서 비껴서 피하고 사거리 끝의 폭발 기절에 주의하세요. (Q)\'부식성 침\'을 사용해 방어력을 낮추며 파밍하고, (E)\'공허의 분비물\'로 애니비아의 접근을 늦추며 거리를 조절해요.', lv3: '(Q)\'냉기 폭발\'에 맞아 냉각된 직후에는 (E)\'동상\' 피해가 커지므로 주의하세요. (W)\'생체마법 폭격\'을 켜서 공격 사거리를 늘리고, 애니비아가 (W)\'결정화\'로 길을 막기 전에 (Q)\'부식성 침\'으로 딜교환을 시작해요.', lv6: '(R)\'얼음 폭풍\' 장판 안에서는 이동 속도가 늦춰지니 (R)\'살아있는 곡사포\'로 멀리서 포격하며 장판 밖에 서세요. 애니비아는 (P)\'환생\'으로 체력을 완전히 회복하니 환생이 남아 있는 동안은 무리하게 마무리를 노리지 마세요. 라인을 당겨 정글러의 개입에 대비하세요.', item: '첫 코어로 구인수의 격노검을 가서 공격 속도를 높이세요. 신발은 애니비아의 마법 피해와 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'로 인한 기절을 풀 수 있어요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'을 사용하여 거리에서 견제하며 스택을 쌓으려 하니 무리하게 맞붙지 마세요. (Q)\'부식성 침\'을 사용하여 방어력을 낮추고 공격 속도를 얻어 미니언과 함께 야스오를 견제해요. (E)\'질풍검\'으로 미니언을 타고 접근하기 전에 거리를 유지하는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 야스오가 (E)\'질풍검\'으로 파고들기 전에 멀리서 공격하세요. 야스오가 (W)\'바람 장막\'을 사용하면 (Q)\'부식성 침\' 같은 투사체가 막히니 벽이 사라진 뒤에 스킬을 맞히세요. (E)\'공허의 분비물\'을 깔아두면 야스오가 (E)\'질풍검\'으로 다가올 때 이동 속도를 늦출 수 있어요.', lv6: '(Q)\'강철 폭풍\'의 중첩이 쌓여 공중에 띄워지면 야스오의 (R)\'최후의 숨결\'에 맞을 수 있으니 주의하세요. (R)\'살아있는 곡사포\'를 활용해 멀리서 체력이 낮은 야스오를 노려 큰 피해를 입히세요. 야스오가 (E)\'질풍검\'으로 들어오는 타이밍에 (E)\'공허의 분비물\'을 사용하여 접근을 방해하며 라인을 관리하세요.', item: '구인수의 격노검을 첫 코어로 선택하여 공격 속도와 효과를 극대화하세요. 신발은 야스오의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오가 (E)\'질풍검\'으로 붙었을 때 점화의 마무리 피해로 킬각을 잡기 편해요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 평타를 사용하며 방어력을 낮추고 (P)\'바위 피부\'로 점점 단단해져요. (Q)\'부식성 침\'으로 먼저 견제하며 거리를 유지하고 오공이 붙으려 하면 (E)\'공허의 분비물\'을 깔아 둔화시키세요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 사거리를 확보한 상태에서 (Q)\'부식성 침\'으로 지속적인 피해를 주세요. 오공이 (E)\'근두운 급습\'으로 돌진할 때 (E)\'공허의 분비물\'을 발밑에 깔아 둔화시키며 거리를 벌려야 해요. 오공의 (W)\'분신 전사\'가 생성한 분신에 스킬을 낭비하지 않도록 주의하세요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 뜨며 스킬을 사용할 수 없으니 매우 조심해야 해요. (R)\'살아있는 곡사포\'로 멀리서 오공의 위치를 드러내고 체력이 낮은 상태라면 강력한 피해를 입혀 킬각을 잡으세요. 오공이 들어오기 전에 (E)\'공허의 분비물\'로 퇴로를 차단하며 라인을 당겨 정글러의 도움을 받으세요.', item: '구인수의 격노검을 첫 코어로 가서 공격 속도를 높여 지속 피해를 늘리세요. 신발은 오공의 기본 공격 피해량을 감소시켜주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 오공이 (E)\'근두운 급습\'으로 들어올 때 탈진을 사용하여 피해량을 감소시키세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던져 멀리서 견제할 수 있으니 거리를 조절하세요. 코그모는 (Q)\'부식성 침\'으로 방어력을 낮추며 미니언과 함께 CS를 챙기세요. 초반에는 오로라의 견제가 강하므로 무리하게 맞붙지 마세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 확보하고 오로라가 다가오지 못하게 하세요. 오로라가 (Q)\'이중 저주\'를 사용했다면 다시 돌아오는 경로를 피해 이동하세요. 오로라의 (E)\'마법의 문\'으로 인한 둔화를 조심하며 (E)\'공허의 분비물\'로 진로를 방해하세요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용해 영역을 만들면 그 안에서 쫓아다니기 어려워요. (R)\'살아있는 곡사포\'로 멀리서 오로라의 체력을 깎으며 영역 밖에서 대응하세요. 오로라가 (W)\'장막 너머로\'로 투명해지면 위치를 확인하기 어려우니 라인 관리에 집중하며 정글러의 개입에 대비하세요.', item: '마법사의 최후를 첫 코어로 가서 공격 속도와 마법 저항력을 동시에 챙기세요. 신발은 오로라의 마법 피해와 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 오로라의 (E)\'마법의 문\'이나 (Q)\'이중 저주\'를 피하며 거리를 유지하세요.' },
    '오른': { lv1: '1~2레벨에는 (Q)\'용암 균열\'이 만드는 기둥 위치를 확인하며 거리를 조절하세요. (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 공격 속도를 높이며 멀리서 평타로 견제하는 것이 좋아요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 멀리서 지속적으로 공격하세요. 오른의 (W)\'불꽃 풀무질\' 마지막 불꽃에 맞으면 불안정 상태가 되어 이동 불가 효과가 길어지니 주의하세요.', lv6: '오른이 (R)\'대장장이 신의 부름\'을 쓰면 정령의 진행 방향을 잘 보고 피해야 해요. (R)\'살아있는 곡사포\'로 멀리서 체력이 낮은 대상을 저격하며 거리를 유지하고 정글러의 개입을 조심하세요.', item: '구인수의 격노검을 첫 코어로 가고 판금 장화를 신으세요. 오른의 물리 피해를 줄이고 공격 속도를 높이기 위해서예요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 오른의 접근을 피하며 거리를 유지하세요.' },
    '올라프': { lv1: '(Q)\'역류\'에 맞으면 방어력이 깎이고 이동 속도가 느려지니 도끼를 피하며 거리를 유지하세요. (W)\'생체마법 폭격\'을 사용해 사거리를 늘리고 멀리서 공격하며 올라프가 접근하지 못하게 해야 해요. 1~2레벨부터 올라프가 근접하면 위험하니 계속 거리를 조절하세요.', lv3: '(Q)\'부식성 침\'을 맞춰서 방어력을 낮춘 뒤에 (W)\'생체마법 폭격\' 효과가 적용된 평타를 계속 넣으세요. 올라프가 (W)\'버티기\'로 보호막을 얻으며 들어올 때는 억지로 딜교하기보다 (E)\'공허의 분비물\'로 둔화를 걸며 거리를 벌리세요. 올라프의 도끼가 빠진 타이밍을 이용해 짧게 딜을 넣고 빠지는 것이 좋아요.', lv6: '(R)\'라그나로크\'를 켠 올라프에게는 기절·속박 같은 이동 불가 효과가 통하지 않으니 (E)\'공허의 분비물\' 둔화로 거리를 벌리며 정면 대결을 피하세요. (R)\'살아있는 곡사포\'를 멀리서 사용하여 체력이 낮은 올라프를 견제하고 접근을 차단하세요. 올라프의 궁극기가 끝날 때까지 거리를 벌리며 기다리다가 다시 딜을 넣는 것이 안전해요.', item: '판금 장화와 구인수의 격노검을 추천해요. 올라프의 기본 공격 피해를 줄이기 위해 판금 장화가 필요하고 구인수의 격노검은 공격 속도를 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 올라프의 (P)\'광전사의 분노\'를 통한 체력 회복 효과를 줄이며 마무리하세요.' },
    '요네': { lv1: '(W)\'생체마법 폭격\'을 사용하여 사거리를 확보하고 요네의 (Q)\'필멸의 검\' 중첩이 쌓이지 않게 거리 조절을 하세요. (Q)\'부식성 침\'을 맞혀 방어력을 낮추며 멀리서 견제하는 것이 편해요. 요네는 두 번째 공격마다 마법 피해를 입히니 근접 딜교환은 피하세요.', lv3: '요네가 (E)\'영혼해방\'을 사용해 영혼 상태가 되면 (E)\'공허의 분비물\'을 깔아 이동을 늦추세요. (Q)\'필멸의 검\' 중첩으로 돌풍이 발생해 띄우기 전에 거리를 벌리는 것이 중요해요. 요네의 (W)\'영혼 가르기\' 보호막이 켜져 있는 동안에는 (W)\'생체마법 폭격\'의 피해가 잘 들어가지 않으니 주의하세요.', lv6: '요네가 (R)\'운명봉인\'을 사용하면 경로에 있는 적을 끌어당기며 띄우니 일직선으로 서 있지 마세요. 요네의 체력이 낮아지면 (R)\'살아있는 곡사포\'로 멀리서 마무리하며 킬을 노리세요. 요네가 (E)\'영혼해방\'으로 들어올 때 (E)\'공허의 분비물\'을 미리 사용하면 대처하기 좋아요.', item: '첫 코어로 구인수의 격노검을 선택하여 공격 속도를 빠르게 올리세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\'로 보호막을 두르고 들어올 때 점화로 마무리 피해를 입히세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 체력을 회복하며 무덤을 생성하니 최대한 거리를 두세요. (Q)\'부식성 침\'으로 요릭의 방어력과 마법 저항력을 낮추며 지속적으로 견제하세요. (P)\'영혼의 길잡이\'로 소환된 망령들이 다가오면 무리하게 싸우지 말고 뒤로 물러나세요.', lv3: '(E)\'애도의 안개\'에 맞으면 망령들이 빠르게 쫓아오니 즉시 (E)\'공허의 분비물\'을 뱉어 이동 속도를 늦추고 거리를 벌리세요. (W)\'망자의 진\' 벽에 갇히면 당황하지 말고 평타로 벽을 빠르게 부수어 탈출하세요. (W)\'생체마법 폭격\'을 켜고 긴 사거리를 이용해 요릭과 망령을 함께 공격하세요.', lv6: '(R)\'군도의 장송곡\'으로 소환된 마녀가 붙으면 피해량이 급증하니 (R)\'살아있는 곡사포\'로 멀리서 체력을 깎으며 대응하세요. 마녀와 망령이 몰려올 때는 무리한 딜교환보다는 라인을 당겨 포탑 근처에서 안전하게 받아치세요. 정글러가 올 때 (Q)\'부식성 침\'으로 적의 저항력을 낮춰두면 빠르게 처치할 수 있어요.', item: '구인수의 격노검을 가서 (W)\'생체마법 폭격\'의 최대 체력 비례 피해를 더 자주 입히세요. 신발은 요릭과 망령의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (Q)\'최후의 의식\'으로 회복하는 요릭의 체력을 점화로 억제하며 킬각을 잡으세요.' },
    '우디르': { lv1: '우디르는 (E)\'불길 쇄도\'로 빠르게 다가와 첫 평타로 기절시키려 해요. (Q)\'부식성 침\'으로 방어력을 낮추며 최대한 거리를 벌리고, 우디르가 다가오면 뒤로 물러나세요. 1~2레벨에는 기절만 피하면 평타로 계속 괴롭힐 수 있어요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 체력 비례 피해를 입히세요. 우디르가 (E)\'불길 쇄도\'로 진입할 때 (E)\'공허의 분비물\'을 발밑에 깔아 둔화시켜 추격 속도를 늦추세요. 우디르가 (W)\'강철 갑옷\'으로 보호막을 얻었을 때는 딜교환을 잠시 멈추고 보호막이 사라진 뒤에 다시 공격하세요.', lv6: '우디르의 체력이 낮아지면 (R)\'살아있는 곡사포\'를 사용해 멀리서 마무리하세요. 우디르가 (E)\'불길 쇄도\'를 재사용하면 이동 불가 및 방해 효과에 면역이 되니 이때는 무리하지 말고 거리를 유지하세요. (R)\'날개 돋친 폭풍\'의 둔화 범위 밖에서 (W)\'생체마법 폭격\' 평타로 일방적인 딜교환을 이어가세요.', item: '구인수의 격노검과 판금 장화를 추천해요. 구인수의 격노검으로 (W)\'생체마법 폭격\'의 체력 비례 피해를 더 자주 입히고, 판금 장화로 우디르의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복할 때 점화로 회복량을 줄여 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳의 (Q)\'부식성 폭약\'은 둔화를 걸며 거리를 좁히니 사거리를 유지하며 미니언을 챙기세요. (Q)\'부식성 침\'을 사용하여 우르곳의 방어력을 낮추며 멀리서 평타로 견제하는 것이 좋아요. 우르곳이 (P)\'화염의 메아리\'를 활용해 평타를 치러 올 때 적절히 거리를 벌리세요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 사거리를 늘린 뒤 (Q)\'부식성 침\'으로 우르곳의 방어력을 깎으며 딜교환을 하세요. 우르곳이 (E)\'경멸\'로 돌진하며 기절을 시키려 할 때는 (E)\'공허의 분비물\'을 발 밑에 깔아 이동 속도를 늦추세요. 우르곳의 (E)\'경멸\'이 빠진 타이밍에 긴 사거리를 활용해 공격을 이어가세요.', lv6: '우르곳의 (R)\'불사의 공포\'는 체력이 낮은 적을 제압하여 처형할 수 있으니 체력이 낮을 때는 무리하게 싸우지 마세요. (R)\'살아있는 곡사포\'를 사용하여 멀리서 우르곳의 체력을 깎으며 라인을 관리하고 정글러의 개입을 유도하세요. 우르곳이 (E)\'경멸\'로 접근할 때 (E)\'공허의 분비물\'을 사용하여 거리를 유지하는 것이 중요해요.', item: '첫 코어로 구인수의 격노검을 가서 지속적인 피해를 입히세요. 신발은 우르곳의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 우르곳의 돌진을 피하며 거리를 벌리고 지속적으로 딜을 넣기 위해서예요.' },
    '워윅': { lv1: '1~2레벨에는 (W)\'생체마법 폭격\'을 켜서 최대한 거리를 벌리며 미니언을 챙기세요. 워윅이 (Q)\'야수의 송곳니\'로 빠르게 접근해 체력을 회복하려 하니 무리하게 평타를 치지 마세요. (Q)\'부식성 침\'을 활용해 워윅의 방어력을 낮추며 거리를 유지하는 것이 중요해요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용하면 받는 피해가 줄어드니 그동안은 공격을 아끼세요. (E)\'공허의 분비물\'로 발밑에 흔적을 남겨 워윅의 접근을 늦추며 (Q)\'부식성 침\'을 맞춰 방어력을 낮추세요. 워윅의 (Q)\'야수의 송곳니\'가 빠진 뒤에 (W)\'생체마법 폭격\'을 켜고 거리를 두며 딜을 넣어야 해요.', lv6: '워윅이 (R)\'무한의 구속\'으로 달려들면 제압 상태가 되어 아무것도 할 수 없으니 주의하세요. 제압은 정화로 풀 수 없으므로 체력이 낮을 때 워윅이 근처에 있다면 뒤로 물러나야 해요. 멀리서 (R)\'살아있는 곡사포\'를 사용해 워윅의 체력을 깎아 놓으면 전투에서 앞서나갈 수 있어요.', item: '구인수의 격노검을 올려 공격 속도를 높여 딜을 넣으세요. 신발은 워윅의 마법 피해와 (E)\'원시의 포효\' 공포 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 워윅의 (Q)\'야수의 송곳니\'나 (P)\'끝없는 허기\'를 통한 체력 회복을 점화로 억제해야 해요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'를 미니언에 사용해 순식간에 거리를 좁히며 체력을 회복하니 주의하세요. 코그모는 (Q)\'부식성 침\'을 활용해 멀리서 먼저 견제하며 거리를 벌려야 해요. 미니언 근처에 너무 붙어 있으면 이렐리아의 돌진에 노출되기 쉬워요.', lv3: '이렐리아의 (E)\'쌍검협무\'는 두 칼날이 만나는 지점에서 기절을 유발하니 그 길목을 피하며 (W)\'생체마법 폭격\'으로 사거리를 유지하세요. 이렐리아가 (W)\'저항의 춤\'을 사용해 받는 물리 피해를 줄이는 동안에는 무리하게 딜교환을 하지 마세요. (E)\'공허의 분비물\'을 사용하여 이렐리아의 이동 경로에 둔화를 거는 것이 좋아요.', lv6: '이렐리아가 (R)\'선봉진격검\'을 사용해 결계를 만들면 둔화에 걸리지 않도록 위치를 잡으세요. (R)\'살아있는 곡사포\'로 멀리서 이렐리아의 체력을 깎아두면 진입을 억제하는 데 도움이 돼요. 이렐리아가 (Q)\'칼날 쇄도\'로 들어와 체력을 회복하기 전에 빠르게 대응해야 해요.', item: '구인수의 격노검을 첫 코어로 선택하여 (W)\'생체마법 폭격\'의 효율을 극대화하세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. 이렐리아의 (E)\'쌍검협무\' 기절을 정화로 빠르게 풀 수 있어요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에서 촉수 공격을 하니 항상 벽에서 멀리 떨어져서 위치를 잡으세요. (Q)\'부식성 침\'의 긴 사거리를 활용해 일라오이가 (Q)\'촉수 강타\'를 쓰기 전에 먼저 공격하며 체력을 깎아 놓으세요. 상대가 다가오려고 하면 계속 뒤로 물러나며 거리 조절을 해주세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 늘어난 사거리로 계속 공격하고 (E)\'공허의 분비물\'로 일라오이의 접근을 늦추세요. (E)\'영혼의 시험\'에 맞으면 영혼이 받은 피해가 나에게 전달되고 영혼에서 멀어지면 숙주가 되어 촉수가 소환되니 매우 조심하세요. (W)\'혹독한 가르침\'의 돌진 사거리가 짧으므로 그 범위 밖에서 일방적으로 공격하는 구도를 유지하세요.', lv6: '(R)\'믿음의 도약\'에 맞으면 촉수가 소환되고 한동안 촉수가 더 빠르게 후려치니 일라오이가 궁극기를 쓰면 즉시 범위를 벗어나세요. (R)\'살아있는 곡사포\'를 사용해 아주 먼 거리에서 체력이 낮은 일라오이를 마무리하며 피해를 누적하세요. 일라오이가 무리하게 진입하면 정글러를 호출해 함께 대응하고 라인을 당겨서 받아먹으세요.', item: '구인수의 격노검을 첫 코어로 선택해 공격 속도를 높이고 (W)\'생체마법 폭격\'의 효율을 극대화하세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 촉수가 있는 벽 근처에서 빠르게 벗어나며 거리를 벌리세요.' },
    '자크': { lv1: '(Q)\'부식성 침\'으로 자크의 방어력을 깎으며 지속적으로 체력을 깎으세요. 자크의 (Q)\'탄성 주먹\' 사거리 밖에서 움직이며 붙잡히지 않도록 거리를 조절하세요. (P)\'세포 분열\' 조각을 주워 체력을 회복하려는 자크의 동선을 방해하며 압박하세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 최대 체력 비례 피해로 자크를 괴롭히세요. 자크가 (E)\'새총 발사\'로 몸을 날려 띄우려 할 때 (E)\'공허의 분비물\'을 발밑에 깔아 둔화시키며 피하세요. (Q)\'탄성 주먹\'에 잡히지 않도록 주의하며 원거리에서 일방적인 교환을 이어가세요.', lv6: '자크가 (R)\'바운스!\'로 튀어 오르면 공중에 떠 있는 동안 스킬을 쓸 수 없으니 빠르게 거리부터 벌리세요. (R)\'살아있는 곡사포\'를 사용해 체력이 낮은 자크에게 큰 피해를 입히고 마무리하세요. 자크가 쓰러져 (P)\'세포 분열\' 조각으로 갈라졌을 때 조각들이 합쳐지기 전에 빠르게 정리하는 것이 중요해요.', item: '구인수의 격노검을 첫 코어로 선택해 공격 속도와 주문력을 챙기고 체력 비례 피해 효율을 높이세요. 신발은 자크의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 자크의 진입 스킬을 피하고, 점화로 (P)\'세포 분열\'을 통한 체력 회복을 억제하며 킬각을 잡으세요.' },
    '자헨': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 사용하여 자헨의 방어력을 낮추며 견제하세요. (W)\'생체마법 폭격\'을 사용해 사거리를 확보하고 자헨이 (Q)\'다르킨의 글레이브\'로 다가오기 전에 거리를 유지하세요. 자헨이 평타와 스킬로 체력을 회복하며 붙지 못하도록 주의하며 받아내야 해요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 하면 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추세요. 자헨이 (E)\'찬란한 쇄도\'로 돌진할 때 (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 거리를 벌려야 해요. (Q)\'다르킨의 글레이브\'로 인해 공중에 띄워지지 않도록 조심하며 딜교환을 하세요.', lv6: '자헨이 (R)\'단호한 판결\'로 내려찍으며 체력을 회복할 수 있으니 착지 지점을 잘 피하세요. 자헨은 결심이 가득 차면 (P)\'전쟁 단련\'으로 부활할 수 있으니 결심 중첩을 확인하며 (R)\'살아있는 곡사포\'로 마무리를 노리세요. 자헨이 (W)\'공포의 귀환\'으로 들어오는 타이밍에 맞춰 거리 조절을 하며 대응하세요.', item: '첫 코어로 구인수의 격노검을 선택해 공격 속도를 높이세요. 신발은 자헨의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 자헨의 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'에 의한 체력 회복을 줄이세요.' },
    '잭스': { lv1: '1~2레벨에는 잭스가 (Q)\'도약 공격\'으로 붙기 전에 (Q)\'부식성 침\'으로 계속 체력을 깎으세요. (P)\'가차없는 맹공\' 때문에 붙어서 평타를 주고받으면 위험하니 최대한 거리를 벌리며 견제하세요. 잭스가 무리하게 다가오면 뒤로 물러나 아군 포탑 쪽으로 끌어들이세요.', lv3: '(E)\'반격\'이 켜지면 평타를 절대 치지 말고 (E)\'공허의 분비물\'을 깔아 둔화시킨 뒤 뒤로 빠지세요. (W)\'생체마법 폭격\'으로 사거리를 늘려 먼저 피해를 넣고, 잭스가 (Q)\'도약 공격\'으로 붙으면 그때 거리를 다시 벌리세요. 잭스가 (W)\'무기 강화\'를 켜고 들어올 때 (E)\'공허의 분비물\'로 접근을 늦추는 것이 중요해요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용하면 방어력과 마법 저항력이 오르니 궁극기 지속시간에는 정면 승부를 피하세요. 체력이 낮아진 잭스에게 (R)\'살아있는 곡사포\'를 쏴서 마무리하고 (E)\'반격\'의 기절에 걸리지 않게 거리 조절을 하세요. 잭스가 (Q)\'도약 공격\'으로 들어올 때 정글러를 호출하기 좋게 라인을 적절히 당겨서 관리하세요.', item: '구인수의 격노검과 판금 장화를 추천해요. 구인수의 격노검은 공격 속도와 주문력을 제공하고, 판금 장화는 기본 공격으로 받는 피해량을 줄여줘요.', spell: '점멸과 정화를 추천해요. 잭스의 (E)\'반격\'으로 인한 기절을 정화로 빠르게 풀고 거리 조절을 할 수 있어요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 쏘며 견제할 때 투사체 경로에서 비껴나세요. (Q)\'부식성 침\'을 먼저 맞혀 방어력과 마법 저항력을 낮춘 뒤 사거리를 유지하며 공격해요. 제이스가 해머 형태로 (Q)\'하늘로!\'를 쓰며 들어오면 거리를 벌리며 대응하세요.', lv3: '제이스가 (E)\'가속 관문\'을 열고 (Q)\'전격 폭발\'을 쏘면 피해가 커지니 즉시 옆으로 피하세요. (W)\'생체마법 폭격\'을 켜서 늘어난 사거리로 제이스가 다가오지 못하게 공격해요. 제이스가 해머 (E)\'천둥 강타\'로 밀쳐내려 하면 (E)\'공허의 분비물\'을 사용하여 이동 속도를 늦추세요.', lv6: '제이스가 (R)\'머큐리 캐논\'으로 변환한 뒤 첫 공격으로 방어력과 마법 저항력을 깎을 때 조심하세요. 제이스의 체력이 낮아지면 (R)\'살아있는 곡사포\'를 사용하여 마무리 피해를 입혀요. 제이스가 해머로 돌아와 붙으려 하면 (E)\'공허의 분비물\'을 깔아 추격을 방해하세요.', item: '구인수의 격노검을 첫 코어로 가서 (W)\'생체마법 폭격\'의 피해를 높이세요. 신발은 공격 속도를 올려주는 광전사의 군화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 이동 속도를 높여 제이스가 해머로 붙은 뒤에도 거리를 다시 벌릴 수 있어요.' },
    '초가스': { lv1: '초가스가 (Q)\'파열\'로 띄우려 할 때 지면 표시를 보고 빠르게 벗어나세요. (Q)\'부식성 침\'으로 방어력을 깎으며 거리 조절을 하고 평타 견제를 하세요. (E)\'날카로운 가시\'가 정면에 둔화를 주니 정면에서 오래 머무르지 마세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 (Q)\'파열\' 범위 밖에서 공격하세요. (W)\'흉포한 울부짖음\'의 침묵에 걸리면 스킬을 못 쓰니 원뿔 범위 밖으로 빠르게 피하세요. 초가스가 다가올 때 (E)\'공허의 분비물\'로 이동 속도를 늦춰 거리를 벌리세요.', lv6: '(R)\'살아있는 곡사포\'로 아주 멀리서 체력을 깎아 놓으면 안전하게 딜교환이 가능해요. 초가스의 (R)\'포식\'은 큰 고정 피해를 입히므로 체력이 낮을 때 가까이 붙지 마세요. 라인을 당겨 정글 개입을 대비하고 (Q)\'파열\'에 맞지 않도록 주의하세요.', item: '구인수의 격노검을 가서 최대 체력 비례 피해를 극대화하세요. 신발은 초가스의 마법 피해와 둔화 지속시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (Q)\'파열\'이나 (W)\'흉포한 울부짖음\'의 사거리 밖으로 빠르게 벗어나기 좋아요.' },
    '카밀': { lv1: '카밀은 (P)\'적응형 방어 체계\' 보호막을 이용해 평타 교환이 강해요. (Q)\'부식성 침\'을 사용하여 거리를 유지하며 상대의 방어력을 낮추세요. (W)\'생체마법 폭격\'을 켜서 카밀이 접근하기 어려운 위치를 선점하는 것이 중요해요.', lv3: '카밀이 (E)\'갈고리 발사\'로 진입할 때 (E)\'공허의 분비물\'을 사용해 이동 속도를 늦추세요. (W)\'전술적 휩쓸기\'의 바깥쪽을 맞으면 카밀이 체력을 회복하니 주의해야 해요. (W)\'생체마법 폭격\'으로 사거리를 늘려 카밀의 (Q)\'정확성 프로토콜\' 사거리 밖에서 공격하세요.', lv6: '카밀이 (R)\'마법공학 최후통첩\'을 사용하면 지역 안에서 탈출할 수 없으니 주의하세요. (R)\'살아있는 곡사포\'를 사용하여 체력이 낮은 카밀을 멀리서 마무리하세요. 카밀이 진입하기 전에 (R)\'살아있는 곡사포\'로 체력을 미리 깎아두는 것이 좋아요.', item: '구인수의 격노검을 첫 코어로 선택해 공격 속도와 적중 시 효과를 챙기세요. 신발은 카밀의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 카밀이 돌진하여 공격할 때 탈진을 사용하여 피해량을 줄이세요.' },
    '카사딘': { lv1: '(Q)\'부식성 침\'을 사용하여 상대의 방어력을 낮추며 견제해요. 카사딘이 (Q)\'무의 구체\'로 보호막을 얻기 전에 지속적으로 공격하여 체력을 깎아두세요. 거리를 멀리 유지하며 미니언을 챙기는 데 집중해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리가 긴 점을 활용하며 공격해요. 카사딘이 (E)\'힘의 파동\'을 사용하여 둔화를 걸려고 할 때 거리를 조절하며 피해야 해요. 상대의 스킬을 피하면서 지속적인 평타 피해를 입히는 것이 중요해요.', lv6: '(R)\'살아있는 곡사포\'로 멀리서 체력이 낮은 적을 저격하며 압박해요. 카사딘이 (R)\'균열 이동\'으로 갑자기 접근할 수 있으니 주의하며 거리를 유지해요. (E)\'공허의 분비물\'을 사용하여 상대의 접근을 늦추며 생존에 유의하세요.', item: '헤르메스의 발걸음과 구인수의 격노검을 가요. 카사딘의 마법 피해에 대비하고 공격 속도를 높이기 위해서예요.', spell: '점멸과 정화를 추천해요. 정화로 (E)\'힘의 파동\' 둔화를 풀 수 있고, 점멸로 (R)\'균열 이동\' 접근 뒤에 거리를 벌릴 수 있어요.' },
    '카시오페아': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 사용하여 상대의 마법 저항력을 낮추며 미니언을 챙기세요. 카시오페아의 (Q)\'맹독 폭발\'을 맞지 않도록 거리를 유지하는 것이 중요해요. (W)\'생체마법 폭격\'을 사용하기 전에는 상대의 견제를 잘 받아내야 해요.', lv3: '3레벨 이후에는 (E)\'공허의 분비물\'을 깔아 카시오페아의 접근을 늦추세요. (Q)\'맹독 폭발\'에 중독되면 (E)\'쌍독니\' 피해가 커지고 카시오페아가 체력을 회복하니 독을 피하며 (W)\'생체마법 폭격\'으로 거리를 두고 피해를 입혀야 해요. (W)\'독기의 늪\'에 닿지 않도록 주의하며 딜교환을 하세요.', lv6: '6레벨 이후에는 (R)\'살아있는 곡사포\'를 사용해 멀리서 적을 압박하며 체력을 깎으세요. 카시오페아의 (R)\'석화의 응시\'를 정면으로 바라보지 않도록 주의하며 라인 관리를 철저히 하세요. 정글러의 개입에 대비해 안전하게 성장하며 체력이 낮은 상대를 (R)\'살아있는 곡사포\'로 마무리하세요.', item: '헤르메스의 발걸음과 구인수의 격노검을 가세요. 마법 저항력을 얻어 카시오페아의 공격을 견디고 공격 속도를 빠르게 올리기 위해서예요.', spell: '점멸과 유체화를 선택하세요. 카시오페아의 스킬을 피하며 거리를 유지하고 안정적으로 공격하기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 (P)\'폭풍의 표식\'을 쌓으며 멀리서 견제해요. (Q)\'부식성 침\'을 사용해 방어력을 낮추고 사거리 차이를 이용해 평타를 섞어주세요. 표식이 쌓이지 않게 케넨의 표창 궤적을 잘 피하며 거리를 유지하세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 늘어난 사거리로 케넨이 다가오기 전에 공격하세요. 케넨이 (E)\'번개 질주\'로 진입하면 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추며 거리를 벌리세요. 케넨의 (W)\'전류 방출\'이 빠진 것을 확인하고 딜교환을 시도하는 것이 좋아요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 켜고 진입하면 기절에 걸릴 수 있으니 주의하세요. (R)\'살아있는 곡사포\'를 사용하여 케넨의 위치를 드러내고 멀리서 지속적으로 마법 피해를 입히세요. 케넨의 스킬이 빠진 타이밍에 정글러와 함께 압박하면 좋은 흐름을 만들 수 있어요.', item: '헤르메스의 발걸음을 선택해 케넨의 마법 피해와 기절 지속 시간을 줄이세요. 첫 코어 아이템으로는 공격 속도를 높여주는 구인수의 격노검을 추천해요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 걸리는 기절은 정화로 빠르게 풀 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\' 성장이 필요해 초반에는 사거리가 짧아요. (W)\'생체마법 폭격\'을 켜고 긴 사거리를 이용해 케일의 체력을 깎아두세요. 케일이 (Q)\'광휘의 일격\'을 쓰며 다가오면 거리를 유지하며 견제하세요.', lv3: '(Q)\'부식성 침\'을 맞춰 방어력을 낮춘 뒤 (W)\'생체마법 폭격\' 사거리로 지속적인 피해를 주세요. 케일이 (E)\'화염주문검\'을 사용해 체력이 낮은 대상에게 큰 피해를 줄 수 있으니 체력 관리에 유의하세요. 케일의 (Q)\'광휘의 일격\' 둔화를 맞았다면 (E)\'공허의 분비물\'로 발밑에 흔적을 남겨 케일의 접근을 늦추세요.', lv6: '케일이 (R)\'신성한 심판\'을 사용해 무적 상태가 되면 딜을 넣을 수 없으니 궁극기 사용 여부를 꼭 확인하세요. (R)\'살아있는 곡사포\'를 활용해 멀리서 케일의 체력을 깎아 킬각을 노려보세요. 케일이 성장하기 전에 라인을 강하게 밀어 정글러의 도움을 받는 것이 좋아요.', item: '구인수의 격노검을 첫 코어로 올려 공격 속도를 확보하세요. 신발은 케일의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택해요.', spell: '점멸과 점화를 추천해요. 점화로 케일의 체력을 깎으며 초반에 격차를 벌리세요.' },
    '코르키': { lv1: '첫 웨이브에서는 (Q)\'인광탄\'의 피해를 최소화하며 신중하게 CS를 챙기세요. (Q)\'부식성 침\'을 사용하여 상대의 방어력을 낮추고 평타 딜교환을 시도하되 무리하게 다가가지 마세요. 상대가 공격적으로 나올 때는 거리 조절에 집중하며 체력을 보존하세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 원거리에서 일방적인 딜교환을 시도하세요. 상대가 (W)\'발키리\'로 진입하거나 (E)\'개틀링 건\'을 사용할 때 (E)\'공허의 분비물\'을 발밑에 깔아 이동 속도를 늦추며 대응하세요. 상대의 핵심 스킬이 빠진 타이밍에 평타를 쏟아부으세요.', lv6: '(R)\'살아있는 곡사포\'를 사용하여 매우 먼 거리에서 상대의 체력을 갉아먹으며 압박하세요. 상대의 (R)\'미사일 폭격\' 세 번째 탄환은 피해가 매우 크니 각별히 주의하며 피하세요. 라인을 밀어두고 정글러를 불러 (R)\'살아있는 곡사포\'로 지원 사격하며 킬각을 잡으세요.', item: '구인수의 격노검을 첫 코어로 가세요. 구인수의 격노검은 공격 속도와 주문력을 제공하고, 신발은 마법 저항력을 높여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀와 운영을 하고 점멸로 생존하거나 공격적인 각을 잡으세요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식이 남은 대상에게 첫 평타가 강하니 최대한 거리를 유지하세요. 1~2레벨에는 (Q)\'부식성 침\'으로 먼저 견제하며 미니언을 챙기세요. 퀸이 (E)\'공중제비\'로 들어오면 빠르게 뒤로 물러나야 해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 늘어난 사거리로 퀸을 압박하세요. 퀸이 (E)\'공중제비\'로 돌진해 (P)\'매사냥\'을 묻히려 하면 (E)\'공허의 분비물\'을 깔아 이동 속도를 늦추며 대응하세요. 퀸의 (E)\'공중제비\'가 빠진 타이밍에 (Q)\'부식성 침\'을 맞춰 지속적으로 딜교환을 하세요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 움직이면 라인을 밀어두고 정글러를 불러 함께 맵을 확인하세요. 체력이 낮은 퀸에게 (R)\'살아있는 곡사포\'를 적중시키면 큰 피해를 입힐 수 있어요. 퀸이 (R)\'후방 지원\' 이후 공중 강습으로 들어올 때 (E)\'공허의 분비물\'로 거리를 조절하는 것이 중요해요.', item: '판금 장화와 구인수의 격노검을 먼저 올리세요. 퀸의 물리 피해를 줄이고 (W)\'생체마법 폭격\'의 효율을 높이기 위해서예요.', spell: '점멸과 유체화를 추천해요. 유체화로 퀸의 (E)\'공중제비\' 추격이나 빠른 이동 속도를 따라잡으며 거리를 벌리세요.' },
    '크산테': { lv1: '(Q)\'부식성 침\'으로 방어력을 낮추며 최대한 멀리서 견제하세요. 크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 다가오면 무리하게 딜교하지 말고 뒤로 물러나세요. 중첩이 쌓여 끌어당기는 충격파가 나오지 않도록 거리를 유지하는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 최대 체력 비례 피해로 괴롭히세요. 크산테가 (E)\'발놀림\'이나 (W)\'길을 여는 자\'로 진입하려고 하면 (E)\'공허의 분비물\'을 뱉어 이동 속도를 늦추며 거리를 벌리세요. (W)\'길을 여는 자\'는 저지 불가 상태로 돌진해 기절시키니 충전 동작이 보이면 즉시 옆으로 피하세요.', lv6: '(R)\'총공세\'에 밀려 벽을 뚫고 이동하면 정글러의 개입에 취약해지니 벽 근처에 서지 마세요. 크산테가 (R)\'총공세\' 상태가 되면 방어력이 낮아지므로 (R)\'살아있는 곡사포\'를 쏘아 체력을 빠르게 깎으세요. 상대의 돌진기가 빠진 틈을 타서 사거리 밖에서 일방적으로 공격하며 라인을 유지하세요.', item: '구인수의 격노검을 첫 코어로 가서 공격 속도와 주문력을 챙기고 체력 비례 피해 효율을 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'길을 여는 자\'의 기절 효과를 정화로 즉시 풀고 거리를 벌릴 수 있어요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 끌어당긴 후 (E)\'이랴!\'로 빠르게 접근하니 거리 조절이 중요해요. (Q)\'부식성 침\'을 사용하여 적의 방어력을 낮추며 멀리서 꾸준히 견제하세요. 1~2레벨 구간에서는 무리한 교전보다는 최대한 거리를 벌려야 해요.', lv3: '클레드가 (E)\'이랴!\'로 돌진해 오면 (W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 위치를 옮기세요. (W)\'버럭버럭\'으로 공격 속도가 빨라진 클레드와는 근접해서 싸우지 않는 것이 좋아요. (E)\'공허의 분비물\'을 발밑에 사용하여 클레드의 접근을 늦추며 딜교환하세요.', lv6: '클레드가 (R)\'돌겨어어억!!!\'을 사용해 보호막을 들고 들어오면 (R)\'살아있는 곡사포\'로 최대한 멀리서 대응하세요. 클레드가 스칼에서 내린 상태라면 (R)\'살아있는 곡사포\'의 피해로 빠르게 처치할 수 있어요. 라인을 당겨 관리하며 정글러의 개입을 유도하는 것이 중요해요.', item: '내셔의 이빨을 첫 코어로 가서 공격 속도와 주문력을 모두 챙기세요. 신발은 공격 속도를 높여주는 광전사의 군화가 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화를 사용하면 클레드의 돌진을 피하며 거리를 조절하기 편해요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 둔화를 주고 (P)\'절대 미각\' 중첩을 쌓으려 해요. (Q)\'혀 채찍\'은 처음 맞는 유닛에 막히니 미니언 뒤에 서서 피해를 피하세요. (Q)\'부식성 침\'을 계속 맞혀 방어력과 마법 저항력을 깎으며 거리를 유지하세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 늘어난 사거리로 탐 켄치의 높은 체력에 비례하는 피해를 꾸준히 넣으세요. 탐 켄치가 (W)\'심연 잠수\'로 진입해 공중으로 띄우려 하면 빠르게 범위 밖으로 벗어나세요. (E)\'공허의 분비물\'로 둔화를 걸어 (Q)\'혀 채찍\'에 맞지 않게 조절하며 짧게 딜교환하세요.', lv6: '(R)\'살아있는 곡사포\'를 이용해 아주 멀리서 체력을 깎고 킬각을 보세요. (P)\'절대 미각\' 중첩이 세 번 쌓이면 (R)\'집어삼키기\'에 먹혀 큰 피해를 입으니 주의하세요. (W)\'심연 잠수\'가 빠진 타이밍에 (R)\'살아있는 곡사포\'와 평타를 쏟아붓고 빠르게 뒤로 빠지세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 많은 탐 켄치에게 지속적인 마법 피해를 입히세요. 신발은 탐 켄치의 둔화와 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 탐 켄치의 체력 회복을 방해하세요.' },
    '트런들': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 맞혀 방어력과 마법 저항력을 낮추며 계속 견제하세요. 트런들이 (Q)\'깨물기\'로 접근해 공격력을 훔치려 하면 뒤로 물러나며 거리 조절을 하세요. 트런들은 근처에서 유닛이 쓰러질 때마다 (P)\'헌납\'으로 체력을 회복하니 미니언이 많이 죽는 곳에서 오래 싸우지 마세요.', lv3: '트런들이 (E)\'얼음 기둥\'으로 진입 경로를 확보하거나 밀어내려 하니 스킬이 빠질 때까지 기다리세요. (W)\'생체마법 폭격\'을 켜서 사거리를 늘리고 최대 체력 비례 피해로 원거리에서 압박하세요. 트런들이 (W)\'얼음 왕국\'을 깔고 빠르게 다가오면 (E)\'공허의 분비물\'로 이동 속도를 늦추며 거리를 벌리세요.', lv6: '트런들이 (R)\'진압\'을 사용해 체력과 방어력을 훔치면 매우 위험하니 즉시 거리를 벌리세요. 트런들의 체력이 낮아졌을 때 (R)\'살아있는 곡사포\'를 퍼부어 마무리 킬각을 잡으세요. (E)\'얼음 기둥\'에 막혀 도망치지 못하면 정글러의 개입에 취약하니 항상 퇴로를 확인하세요.', item: '구인수의 격노검과 판금 장화를 추천해요. 판금 장화는 (Q)\'깨물기\' 같은 기본 공격 피해를 줄여주고, 구인수의 격노검은 공격 속도를 높여 (W)\'생체마법 폭격\'의 효율을 극대화해요.', spell: '점멸과 점화를 추천해요. 트런들이 (W)\'얼음 왕국\'에서 받는 치유 효과가 증가하므로 점화의 치유 감소로 이를 억제해야 해요.' },
    '트린다미어': { lv1: '트린다미어가 (Q)\'피의 갈망\'을 사용해 체력을 회복하며 접근할 때 거리를 유지하는 것이 중요해요. (Q)\'부식성 침\'을 사용해 방어력을 낮추며 멀리서 견제하고, 트린다미어가 (E)\'회전 베기\'로 붙지 못하도록 주의하세요.', lv3: '(W)\'생체마법 폭격\'을 사용해 사거리를 늘린 상태에서 (E)\'공허의 분비물\'로 트린다미어의 이동 속도를 늦추며 딜교환을 하세요. 트린다미어가 (W)\'조롱의 외침\'으로 공격력을 낮추기 전에 빠르게 거리를 벌리는 것이 좋아요.', lv6: '(R)\'살아있는 곡사포\'로 체력이 낮은 트린다미어를 공격할 수 있지만 (R)\'불사의 분노\'가 켜지면 잠시 공격을 멈추세요. (R)\'불사의 분노\'가 끝난 직후가 가장 좋은 킬 타이밍이니 그때 남은 피해를 집중해서 입히세요.', item: '구인수의 격노검을 첫 코어로 올리고 신발은 트린다미어의 기본 공격 피해를 줄여주는 판금 장화를 선택하세요. 높은 공격 속도로 상대를 압박하세요.', spell: '점멸과 점화를 추천해요. 점화로 트린다미어의 (Q)\'피의 갈망\' 회복 효과를 감소시킬 수 있어요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 평타마다 독 피해를 쌓으며 견제하니 거리를 유지하세요. (Q)\'부식성 침\'을 맞춰 방어력을 낮추고 공격 속도를 얻어 미니언을 챙기세요. 티모가 수풀에 들어가 (P)\'유격 전투\'로 투명해지면 무리하게 다가가지 말고 시야를 확인하세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 확보하고 티모를 멀리서 공격하세요. 티모의 (Q)\'실명 다트\'에 맞으면 평타가 빗나가니, 다트가 빠진 것을 확인한 뒤에 (Q)\'부식성 침\'과 평타로 딜교환을 하세요. 티모가 (W)\'신속한 이동\'으로 도망치려 하면 (E)\'공허의 분비물\'로 이동 속도를 늦추세요.', lv6: '(R)\'살아있는 곡사포\'를 사용해 멀리서 티모를 압박하며 체력이 낮은 타이밍을 노리세요. 길목에 깔린 (R)\'유독성 함정\'은 밟으면 둔화와 함께 모습이 드러나니 주의하며 라인을 관리하세요. 티모가 버섯을 깔아두고 자리를 비우면 정글러를 불러 함께 압박하는 것이 좋아요.', item: '첫 코어로 구인수의 격노검을 가서 (W)\'생체마법 폭격\'의 체력 비례 피해를 더 자주 입히세요. 신발은 티모의 마법 피해를 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 유체화를 추천해요. 유체화로 티모의 (W)\'신속한 이동\'을 따라잡거나 거리를 조절하며 공격하기 편해요.' },
    '판테온': { lv1: '판테온이 (Q)\'혜성의 창\'을 던지며 압박할 때 최대한 거리를 유지하며 (Q)\'부식성 침\'으로 방어력을 낮추며 견제하세요. 판테온이 (P)\'필멸자의 의지\'를 쌓아 강화된 스킬을 쓰려 한다면 무리하게 딜교환을 하지 말고 뒤로 물러나야 해요. 첫 웨이브 구간부터 판테온의 사거리 안에 들어가지 않도록 주의하세요.', lv3: '(W)\'생체마법 폭격\'을 켜고 (Q)\'부식성 침\'으로 방어력을 낮춘 뒤 늘어난 사거리로 평타를 넣으세요. 판테온의 (W)\'방호의 도약\'은 대상에게 돌진해 기절시키는 스킬이라 걸어서 피할 수 없으니 도약이 빠진 것을 확인한 뒤에 길게 딜교환을 하세요. (E)\'방패 돌격\'을 든 방향의 피해는 막히니 그동안은 공격을 멈추고 거리를 벌렸다가 방패가 끝나면 다시 공격하세요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 공중으로 뛰어오르면 착지 지점을 파악해 빠르게 범위 밖으로 벗어나세요. (R)\'살아있는 곡사포\'를 활용해 멀리서 체력이 낮은 판테온을 저격하며 딜을 넣으세요. 판테온이 사라지면 다른 라인에 개입하려는 신호일 수 있으니 미니맵을 확인하며 라인을 관리하세요.', item: '구인수의 격노검을 첫 코어로 가서 공격 속도를 높이세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'방호의 도약\'으로 걸리는 기절을 정화로 빠르게 풀 수 있어요.' },
    '피들스틱': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 사용해 원거리에서 계속 견제하세요. 상대가 (Q)\'공포\'를 사용하기 위해 시야 밖으로 숨지 못하게 압박하며 거리 조절을 하는 것이 중요해요. 미니언에 가리지 않는 각도에서 (Q)\'부식성 침\'을 맞혀 상대의 방어력과 마법 저항력을 깎아두세요.', lv3: '(W)\'생체마법 폭격\'을 켜고 더 먼 거리에서 일방적인 딜교환을 시도하세요. 상대의 (E)\'수확\' 중심부에 맞으면 침묵 상태가 되어 스킬을 못 쓰니 범위 끝자락에 맞거나 피해야 해요. (W)\'풍작\'은 근처 적을 흡수하는 스킬이니 (E)\'공허의 분비물\'로 거리를 유지하며 범위 밖에서 싸우세요.', lv6: '상대가 (R)\'까마귀 폭풍\'으로 기습하는 것을 조심하며 시야 확보에 신경 쓰세요. 체력이 낮은 상대에게 (R)\'살아있는 곡사포\'를 발사해 마무리 킬각을 잡는 것이 좋아요. 정글 개입이 심한 구간이니 (E)\'공허의 분비물\'로 거리 조절을 하며 안전하게 라인을 관리하세요.', item: '구인수의 격노검과 헤르메스의 발걸음이에요. 구인수의 격노검은 공격 속도와 주문력을 제공해 (W)\'생체마법 폭격\'의 효율을 높여줘요. 헤르메스의 발걸음은 마법 저항력을 주고 강인함으로 공포 지속시간을 줄여줘요.', spell: '점멸과 정화예요. 정화는 (Q)\'공포\'나 (E)\'수확\'의 침묵 효과를 빠르게 제거해 생존력을 높여줘요.' },
    '피오라': { lv1: '1~2레벨에는 (Q)\'부식성 침\'을 활용해 멀리서 피오라의 체력을 깎으며 거리를 유지하세요. 피오라가 (P)\'치명적인 검무\'의 급소를 노리고 들어오지 못하게 거리 조절을 하는 것이 중요해요. 초반에는 무리하게 맞붙기보다 미니언을 받아먹으며 피오라의 접근을 막으세요.', lv3: '(W)\'생체마법 폭격\'을 켜서 사거리를 늘려 피오라를 공격하세요. 피오라의 (W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내니, (W)\'응수\'가 빠진 타이밍에 맞춰서 딜교환을 시작해야 해요. 피오라가 (Q)\'찌르기\'로 파고들 때 (E)\'공허의 분비물\'로 둔화를 걸어 거리를 벌리는 것도 도움이 돼요.', lv6: '(R)\'살아있는 곡사포\'로 멀리서 피오라를 견제하며 체력을 낮춰두면 킬각을 잡기 수월해요. 피오라가 (R)\'대결투\'를 사용하면 급소를 모두 가격하기 쉬워지니 무리하게 맞서지 말고 뒤로 물러나세요. 라인을 밀어넣고 정글러를 호출하거나 시야를 확보하며 피오라의 접근을 차단하는 것이 좋아요.', item: '판금 장화와 구인수의 격노검을 가세요. 판금 장화는 피오라의 기본 공격 피해를 줄여주고 구인수의 격노검은 공격 속도를 높여줘요.', spell: '점멸과 유체화를 추천해요. 점멸로 (Q)\'찌르기\' 접근에 대비하고, 유체화로 붙은 뒤에도 거리를 다시 벌릴 수 있어요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 압박하니 포탑 범위 안으로 들어가지 마세요. 1~2레벨에는 (Q)\'부식성 침\'으로 하이머딩거를 견제하며 미니언을 챙기고 포탑의 공격을 최대한 피하며 버티는 것이 중요해요.', lv3: '(W)\'생체마법 폭격\'을 사용하여 사거리를 확보하고 하이머딩거가 (E)\'CH-2 전자폭풍 수류탄\'을 던지기 전에 먼저 타격하세요. 수류탄에 기절하지 않도록 투사체를 보고 잘 피해야 하며, (W)\'마법공학 초소형 로켓\'이 한꺼번에 맞지 않게 주의하며 딜을 넣으세요.', lv6: '(R)\'살아있는 곡사포\'로 멀리서 하이머딩거의 체력을 깎아 킬각을 보세요. 하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰면 위험하니, 그 스킬이 빠진 것을 확인하고 (W)\'생체마법 폭격\'과 함께 딜을 넣으세요. 포탑이 많은 곳은 피하고 정글러를 호출하세요.', item: '구인수의 격노검을 첫 코어로 올려서 공격 속도와 지속 딜을 높이세요. 신발은 하이머딩거의 마법 피해와 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 유체화를 추천해요. 유체화로 하이머딩거의 포탑과 (E)\'CH-2 전자폭풍 수류탄\'의 범위를 빠르게 벗어나며 공격하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_kogmaw);
if (typeof module !== 'undefined') module.exports = top_kogmaw;
